      // Sheet L1 + L2 + L3 → the legacy category to STORE (the fold). Split
      // L2s (Cardigans, Suit separates…) resolve per L3 via the tree.
      function _waTaxLegacy(sheet, l2, l3) {
        if (l2 && _waTaxTree) {
          let first = null;
          for (const g of _waTaxTree) {
            if (g.l2 !== l2) continue;
            if (!first) first = g;
            if (l3 && g.l3.indexOf(l3) !== -1) return g.l1;
          }
          if (first) return first.l1;
        }
        return _WA_SHEET_DEFAULT_LEGACY[sheet] || 'Other';
      }
      // Cascading Category / Subcategory / Item type picks — shared by the
      // add/edit form's custom pickers (add/edit redesign 2026-08-05: no
      // native OS dropdown for category). State: __waSawTaxSel {sheet, l2,
      // l3}, null when the tree isn't available (legacy category list).
      function _waTaxSync() {
        const s = window.__waSawTaxSel;
        if (!s) return;
        // Keep the legacy-facing state in step (hidden #wa-cat + save payload).
        window.__waSawCat = _waTaxLegacy(s.sheet, s.l2, s.l3);
        window.__waSawL2  = s.l2;
        window.__waSawL3  = s.l3;
        if (window.__waFormRepaint) window.__waFormRepaint();
      }
      window.__waTaxCatChange = function(v) {
        const s = window.__waSawTaxSel;
        if (!s) return;
        s.sheet = v; s.l2 = ''; s.l3 = '';
        _waTaxSync();
      };
      window.__waTaxL2Change = function(v) {
        const s = window.__waSawTaxSel;
        if (!s) return;
        s.l2 = v; s.l3 = '';
        _waTaxSync();
      };
      window.__waTaxL3Change = function(v) {
        const s = window.__waSawTaxSel;
        if (!s) return;
        s.l3 = v;
        _waTaxSync();
      };

      // Shared garment palette — used by the add/edit modal swatch rows AND
      // the Refine drawer's colour filter (lifted out of the autotag closure).
      const _ALL_SWATCHES = [
        { name: 'White',      hex: '#FFFFFF', tier: 'Foundations' },
        { name: 'Cream',      hex: '#F5F5DC', tier: 'Foundations' },
        { name: 'Navy',       hex: '#2C3E50', tier: 'Foundations' },
        { name: 'Charcoal',   hex: '#4A4A4A', tier: 'Foundations' },
        { name: 'Black',      hex: '#000000', tier: 'Foundations' },
        { name: 'Espresso',   hex: '#2B1E18', tier: 'Foundations' },
        { name: 'Camel',      hex: '#D2B48C', tier: 'Dimension Builders' },
        { name: 'Taupe',      hex: '#8B8589', tier: 'Dimension Builders' },
        { name: 'Olive',      hex: '#556B2F', tier: 'Dimension Builders' },
        { name: 'Aubergine',  hex: '#4B0082', tier: 'Dimension Builders' },
        { name: 'Forest',     hex: '#123524', tier: 'Dimension Builders' },
        { name: 'Bordeaux',   hex: '#4A0E17', tier: 'Dimension Builders' },
        { name: 'Blush',      hex: '#E6C2B6', tier: 'Dimension Builders' },
        { name: 'Ochre',      hex: '#D4AF37', tier: 'Exclamation Points' },
        { name: 'Magenta',    hex: '#FF1493', tier: 'Exclamation Points' },
        { name: 'Cobalt',     hex: '#0047AB', tier: 'Exclamation Points' },
        { name: 'Emerald',    hex: '#00A86B', tier: 'Exclamation Points' },
        { name: 'Vermillion', hex: '#FF4500', tier: 'Exclamation Points' },
        { name: 'Acid',       hex: '#E1FD2E', tier: 'Exclamation Points' },
        { name: 'Multi',      hex: null,      tier: 'Exclamation Points' },
        { name: 'Print',      hex: null,      tier: 'Exclamation Points' },
      ];
      // One background rule per colour name — the form's single swatch, the
      // Change popover and the Refine grid all draw the same dot. Unknown
      // names (old rows saved before the palette) get a quiet cream disc.
      function _waSwatchBg(name) {
        const sw = _ALL_SWATCHES.find(s => s.name === name);
        if (sw && sw.hex) return 'background:' + sw.hex + (sw.hex === '#FFFFFF' ? ';box-shadow:inset 0 0 0 1px #D8CFC0' : '');
        if (name === 'Multi') return 'background:conic-gradient(#FF1493,#FF4500,#E1FD2E,#00A86B,#0047AB,#4B0082,#FF1493)';
        if (name === 'Print') return 'background:repeating-linear-gradient(45deg,#EDE8E0 0 3px,#A89880 3px 4px)';
        return 'background:#EFE9DC;box-shadow:inset 0 0 0 1px #E7E0CF';
      }

      let _waItems = [], _waCat = 'All', _waEditId = null;
      // One-shot callback fired after a NEW wardrobe piece is added + reloaded,
      // with the new row's id. Lets "Snap mine" (daily look / moodboard swap)
      // apply the just-added piece into the look it was launched from.
      let _waAfterAdd = null;
      // Batch add: extra photos queued from a multi-select in step 1. Each
      // saved piece pulls the next photo straight into step 2 (the modal
      // never closes between pieces). `var` on purpose — early readers must
      // see undefined/empty, never throw (see the TDZ gotcha in CLAUDE.md).
      var _waBatchQueue = [], _waBatchTotal = 0, _waBatchDone = 0, _waBatchAdvance = null;

      function _waEsc(s){ return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

      // Downscale + transcode to JPEG (max 1600px) so photo payloads stay
      // small on cellular and HEIC previews render. Falls back to the raw
      // data URL when the browser can't decode the source.
      function _rbDownscale(file) {
        return createImageBitmap(file).then(function(bmp) {
          const scale = Math.min(1, 1600 / Math.max(bmp.width, bmp.height));
          const canvas = document.createElement('canvas');
          canvas.width = Math.round(bmp.width * scale);
          canvas.height = Math.round(bmp.height * scale);
          canvas.getContext('2d').drawImage(bmp, 0, 0, canvas.width, canvas.height);
          bmp.close();
          return canvas.toDataURL('image/jpeg', 0.85);
        }).catch(function() {
          return new Promise(function(resolve, reject) {
            const reader = new FileReader();
            reader.onload = function(e) { resolve(e.target.result); };
            reader.onerror = function() { reject(new Error('unreadable')); };
            reader.readAsDataURL(file);
          });
        });
      }

      // Hosted wardrobe photo → prompt-attachment dataURL. Goes through
      // _rbDownscale so a full-resolution Cloudinary original never lands
      // base64 inside a styling request body (20mb server limit).
      function _rbUrlToDataUrl(url) {
        return fetch(url).then(r => r.blob()).then(_rbDownscale);
      }

      function _waShowToast(msg) {
        const t = document.getElementById('toast-msg') || document.getElementById('toast');
        if (!t) return;
        const wrap = t.id === 'toast-msg' ? t.parentElement : t;
        if (t.id === 'toast-msg') t.textContent = msg; else t.textContent = msg;
        wrap.classList.add('show');
        setTimeout(() => wrap.classList.remove('show'), 2800);
      }

      // Affiliate shopping isn't live — every "Shop via Affiliate" CTA opens
      // the bundle's Coming Soon dialog (closing the swap modal it sits in,
      // which stacks above the dialog).
      window.__rbAffiliateSoon = function(modalId) {
        if (modalId) document.getElementById(modalId)?.remove();
        if (window.KP && KP.comingSoon) {
          KP.comingSoon('Shopping links,<br><em>coming soon.</em>', 'Robes will soon take you straight to this piece at its retailer.');
        } else {
          _waShowToast('Affiliate links coming soon');
        }
      };

      async function _waFetch(method, path, body) {
        const r = await fetch(_SUPA_URL + '/rest/v1/' + path, {
          method,
          headers: {
            'apikey': _SUPA_KEY, 'Authorization': 'Bearer ' + _waToken(),
            'Content-Type': 'application/json', 'Prefer': 'return=representation'
          },
          body: body !== undefined ? JSON.stringify(body) : undefined
        });
        if (!r.ok) throw new Error(await r.text());
        return r.status === 204 ? null : r.json();
      }

      // ── Admin capture (migration 11) — action events + output feedback ──
      // Fire-and-forget inserts with the user's own JWT (RLS own-insert
      // policies). Both degrade silently until the migration runs — a
      // failed insert must never surface to the user or block a flow.
      var _RB_ENV = (location.hostname === 'www.byrobes.com' || location.hostname === 'byrobes.com') ? 'production' : 'beta';
      // Capture inserts MUST use Prefer: return=minimal — the events/feedback
      // tables are insert-only for ordinary users (select is admin-only), and
      // return=representation makes PostgREST run INSERT…RETURNING, whose
      // returned row is checked against SELECT policies → the whole insert
      // fails 42501 for every non-admin. _waFetch (return=representation) is
      // therefore the wrong door for these two tables.
      function _rbCapturePost(table, row) {
        fetch(_SUPA_URL + '/rest/v1/' + table, {
          method: 'POST',
          headers: {
            'apikey': _SUPA_KEY, 'Authorization': 'Bearer ' + _waToken(),
            'Content-Type': 'application/json', 'Prefer': 'return=minimal'
          },
          body: JSON.stringify(row)
        }).then(r => { if (!r.ok) r.text().then(t => console.warn('[robes] capture ' + table + ' failed:', r.status, String(t).slice(0, 160))); })
          .catch(() => {});
      }
      // Per-generation correlation id: sent as `genId` in the generation
      // POST (→ generation_log.detail.gen_id on every LLM call) AND stored
      // inside the saved lookbook entry's data, so the admin panel can walk
      // prompt → calls → artifact for one generation.
      function _rbGenId() { return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 8); }
      function _rbTrack(type, meta) {
        try {
          const uid = _waUid();
          if (!uid || !_waToken()) return;
          _rbCapturePost('events', { user_id: uid, event_type: type, metadata: meta || {}, environment: _RB_ENV });
        } catch (_) {}
      }
      window._rbTrack = _rbTrack;
      function _rbFbCloud(track, itemId, rating, note) {
        try {
          const uid = _waUid();
          if (!uid || !_waToken()) return;
          _rbCapturePost('feedback', {
            user_id: uid,
            lookbook_item_id: itemId != null ? Number(itemId) : null,
            track: track || null,
            rating: rating === 0 || rating === 1 ? rating : null,
            note: note || null,
          });
          _rbTrack('feedback_given', { track: track || '', rating: rating === 0 || rating === 1 ? rating : null });
        } catch (_) {}
      }

      let _waLoadRetries = 0;
      async function _waLoad() {
        try {
          const data = await _waFetch('GET', 'wardrobe_items?user_id=eq.' + _waUid() + '&order=created_at.desc&select=*');
          _waItems = data || [];
          _waLoaded = true;
          _waLoadRetries = 0;
          // The shared tag namespace rides along (ADR-002). Awaited, because
          // the Refine drawer and the add form both read _tgTags on their
          // first paint — and a paint that beat the fetch would render the
          // seven seeds only and silently hide her own tags.
          await _tgLoad();
        } catch(e) {
          console.error('wardrobe load:', e);
          // Transient failure (token refresh, network) — retry so the UI
          // never sits on the bundle's mock counts indefinitely
          if (_waLoadRetries < 3) { _waLoadRetries++; setTimeout(_waLoad, 1500 * _waLoadRetries); }
        }
        _waBuildFilters();
        _waRender();
        _waSyncCounts();
        window.__rbPieceSync && window.__rbPieceSync();
        // Wishlist refresh rides along (fire-and-forget; degrades silently
        // until the wardrobe_v2 migration has run)
        _wlLoad();
      }

      let _waLoaded = false;
      let _waRendering = false; // guard against observer re-entrancy

      // Watch the grid for any external writes (bundle's renderWardrobe) and
      // immediately restore our content whenever they happen.
      const _waObserver = new MutationObserver(() => {
        if (_waRendering) return;
        _waRender();
      });

      function _waObserveGrid() {
        const grid = document.getElementById('wg-grid');
        if (grid) _waObserver.observe(grid, { childList: true });
      }

      function _waRender() {
        const grid = document.getElementById('wg-grid');
        if (!grid) return;
        _waRendering = true;
        _waObserver.disconnect();
        // A full innerHTML swap resets window scroll — starring a piece at
        // the bottom of a 60-item grid used to throw her back to the top.
        const _waScrollY = window.scrollY;
        if (!_waLoaded) {
          grid.innerHTML = '<div style="padding:56px 24px;text-align:center"><div style="font-family:\'Cormorant\',Georgia,serif;font-style:italic;font-weight:300;font-size:18px;color:var(--ink-faint)">Opening your wardrobe…</div></div>';
        } else {
          // Category (primary) + Refine drawer (secondary) filters.
          // In-season hero pieces lead the grid in rack order (integration
          // pass 2026-07-21: no separate rail — heroes live IN the grid);
          // off-season heroes and everything else keep newest-first order.
          const filtered = _waFilteredItems().sort((a, b) => {
            const ah = a.hero_position != null && _waInSeasonNow(a);
            const bh = b.hero_position != null && _waInSeasonNow(b);
            if (ah !== bh) return ah ? -1 : 1;
            return ah ? (a.hero_position || 0) - (b.hero_position || 0) : 0;
          });
          const frag = document.createDocumentFragment();
          if (!_waItems.length) {
            // True cold start — ONE invitation, nothing else (Annie,
            // 2026-08-13: the milestone bar and the add-card grid doubled
            // the same ask on the emptiest screen — the learning meter
            // lives on home, and the add card returns with the first
            // piece). The hero card's two doors are the whole page.
            const invite = document.createElement('div');
            invite.style.cssText = 'grid-column:1/-1;padding:44px 28px;border:0.5px solid var(--rule-mid);border-radius:var(--rad-lg);background:#fff;text-align:center';
            invite.innerHTML =
              '<div style="font-size:10px;font-weight:500;letter-spacing:.2em;text-transform:uppercase;color:var(--ink-faint);margin-bottom:14px">Your wardrobe</div>' +
              '<div style="font-family:\'Cormorant\',Georgia,serif;font-weight:300;font-size:clamp(24px,3vw,32px);color:var(--ink);line-height:1.15;margin-bottom:22px">Every look starts with<em style="font-style:italic"> a photograph.</em></div>' +
              '<button onclick="window.WA&&WA.open&&WA.open()" style="border:none;background:var(--ink);color:#fff;border-radius:100px;padding:14px 28px;font-size:11px;font-weight:500;letter-spacing:.08em;text-transform:uppercase;cursor:pointer;font-family:inherit">Catalogue your wardrobe</button>' +
              '<div style="margin-top:16px"><button onclick="window.WA&&WA.open&&WA.open()" style="border:none;background:none;padding:0;font-size:12.5px;color:var(--ink-soft);border-bottom:0.5px solid var(--rule-mid);cursor:pointer;font-family:inherit">Or photograph what you&rsquo;re wearing now</button></div>';
            frag.appendChild(invite);
          } else if (!filtered.length) {
            // Filter miss is NOT the empty wardrobe — say so, offer the way back.
            const miss = document.createElement('div');
            miss.style.cssText = 'grid-column:1/-1;padding:40px 24px;text-align:center';
            miss.innerHTML =
              '<div style="font-family:\'Cormorant\',Georgia,serif;font-style:italic;font-weight:300;font-size:19px;color:var(--ink-soft);margin-bottom:12px">Nothing matches those filters.</div>' +
              '<button onclick="window.__waFiltersClear&&__waFiltersClear()" style="border:0.5px solid var(--rule-mid);background:#fff;color:var(--ink);border-radius:100px;padding:9px 20px;font-size:11.5px;cursor:pointer;font-family:inherit">Show all ' + _waItems.length + ' pieces</button>';
            frag.appendChild(miss);
          }
          filtered.forEach(it => frag.appendChild(_waCard(it)));
          // The add card rides the grid only once a piece exists — at zero
          // the hero invitation is the one door (the ghost tiles retired
          // with it).
          if (_waItems.length) frag.appendChild(_waAddCard());
          grid.innerHTML = '';
          grid.appendChild(frag);
          _waSyncCounts();
        }
        _waObserver.observe(grid, { childList: true });
        if (_waLoaded && window.scrollY !== _waScrollY) window.scrollTo(0, _waScrollY);
        _waRendering = false;
        // Keep the v2 sections (hero rail, sub-tabs, wishlist) in step —
        // and the tab row's top-ten ranking, which follows the counts.
        if (_waFiltersBuilt) _waTabsPaint();
        _waV2Sync();
        _waTrailSync();
      }

      const _WA_TARGET = 15;

      // ── Milestone capabilities — the learning meter (Homescreen FTUE;
      // reframed 2026-07-29 after the Clodagh test) ─────────────────────
      // Thresholds are config, never literals in the view — re-tune here and
      // the progress card, the wardrobe empty state and the concierge gate
      // all follow. `at` is the piece count that earns the milestone;
      // `label` stays the feature's name (headlines, gating copy); `cap` is
      // what Robes can DO from that count — the bar columns render `cap`,
      // never `label` (capability, not a feature to unlock); `pos` is the
      // tick's % position on the endless track (see _msBarHtml).
      const _MS_UNLOCKS = [
        { at: 3,  key: 'daily',      label: 'Daily look',     cap: 'Dresses today',    pos: 15 },
        { at: 10, key: 'travel',     label: 'Travel edit',    cap: 'Packs your trips', pos: 50 },
        { at: 15, key: 'styleNotes', label: 'Style notes',    cap: 'Knows your taste', pos: 78 },
      ];
      function _msUnlocked(key, n) {
        const u = _MS_UNLOCKS.find(x => x.key === key);
        return !!u && (n == null ? _waItems.length : n) >= u.at;
      }
      function _msNext(n) { return _MS_UNLOCKS.find(u => u.at > n) || null; }

      // "Just unlocked" is a one-session label. _msPrevCount seeds from the
      // last count this browser saw, so a threshold crossed between sessions
      // still reads as earned on the first render back — and crossings made
      // live in-session accumulate on top. var, not let: _waSyncCounts can
      // reach this before execution passes the assignment (TDZ trap).
      var _msPrevCount = null;
      var _msCrossed = {};
      function _msCrossKey() { const u = _waUid(); return u ? 'rb_ms_last__' + u : null; }
      function _msTrack(n) {
        const k = _msCrossKey();
        if (!k) return;
        if (_msPrevCount == null) {
          const raw = parseInt(localStorage.getItem(k), 10);
          _msPrevCount = isNaN(raw) ? n : raw;
        }
        if (n > _msPrevCount) {
          _MS_UNLOCKS.forEach(u => { if (u.at > _msPrevCount && u.at <= n) _msCrossed[u.key] = true; });
        }
        if (n >= _msPrevCount) { _msPrevCount = n; try { localStorage.setItem(k, String(n)); } catch (e) {} }
      }

      const _MS_WORDS = ['no', 'One', 'Two', 'Three', 'Four', 'Five', 'Six', 'Seven',
        'Eight', 'Nine', 'Ten', 'Eleven', 'Twelve', 'Thirteen', 'Fourteen', 'Fifteen'];
      function _msWord(n) { return _MS_WORDS[n] || String(n); }

      // Derived, never authored: names the next unlock and the distance to it,
      // or what was just earned at a boundary.
      function _msHeadline(n) {
        const next = _msNext(n);
        if (!next) return 'Your wardrobe is there —<br>every look is built from it.';
        const left = next.at - n;
        const pieces = left === 1 ? 'more piece' : 'more pieces';
        const reach = next.key === 'daily'
          ? _msWord(left) + ' ' + pieces + ' and Robes<br>dresses you every morning.'
          : _msWord(left) + ' ' + pieces + ' and the<br>' + next.label.toLowerCase() + ' opens.';
        if (n === 0) return 'Three pieces and Robes<br>dresses you every morning.';
        const earned = _MS_UNLOCKS.filter(u => u.at <= n && _msCrossed[u.key]).pop();
        if (earned) return earned.label + ' just opened.<br>' + _msWord(left) + ' ' + pieces + ' for the ' + next.label.toLowerCase() + '.';
        return reach;
      }

      function _msEnsureCss() {
        if (document.getElementById('rb-ms-style')) return;
        const st = document.createElement('style');
        st.id = 'rb-ms-style';
        // --ms-locked is the one tone with no token: light enough to read as
        // not-yet-earned, dark enough to sit visibly on the track.
        st.textContent =
          '.rb-ms{--ms-locked:#C4B8A4;display:flex;flex-direction:column;gap:9px}' +
          // The last quarter of the track fades to near-transparent — the
          // meter has no endpoint to fill (learning meter, 2026-07-29). Mask,
          // not background, so the fill and any tick inside the fade dim too.
          '.rb-ms-track{position:relative;height:3px;background:var(--cream-400);border-radius:2px;' +
            '-webkit-mask-image:linear-gradient(90deg,#000 0,#000 75%,rgba(0,0,0,0.05) 100%);' +
            'mask-image:linear-gradient(90deg,#000 0,#000 75%,rgba(0,0,0,0.05) 100%)}' +
          '.rb-ms-fill{position:absolute;left:0;top:0;bottom:0;background:var(--ink);border-radius:2px;' +
            'transition:width 650ms cubic-bezier(0.4,0,0.2,1)}' +
          '.rb-ms-tick{position:absolute;top:-3px;width:1px;height:9px;background:var(--ms-locked)}' +
          '.rb-ms-tick.on{background:var(--ink-soft)}' +
          '.rb-ms-cols{display:grid;grid-template-columns:repeat(' + _MS_UNLOCKS.length + ',1fr);gap:8px}' +
          '.rb-ms-col{display:flex;align-items:baseline;gap:5px;min-width:0}' +
          '.rb-ms-at{font-family:var(--font-serif);font-size:13px;line-height:1;color:var(--ms-locked);flex:none}' +
          '.rb-ms-col.on .rb-ms-at{color:var(--ink)}' +
          '.rb-ms-lbl{font-size:10px;line-height:1.3;color:var(--ink-soft)}' +
          '.rb-ms-col.on .rb-ms-lbl{color:var(--ink)}' +
          '@media(max-width:520px){.rb-ms-col{flex-direction:column;align-items:flex-start;gap:1px}}' +
          '@media(prefers-reduced-motion:reduce){.rb-ms-fill{transition:none}}';
        document.head.appendChild(st);
      }

      // The one milestone bar — home progress card and the wardrobe empty
      // state render the identical component so the promise reads the same
      // in both places. A LEARNING meter, not a completion meter (Clodagh
      // test 2026-07-29 — the old n/15 fraction read as the wardrobe's item
      // limit): the track is scaled to _MS_SCALE so the last milestone sits
      // at 78%, the final quarter fades out (no endpoint to fill), and the
      // columns name capability (`cap`), never a feature to unlock.
      // Structure only: no per-tick status text. "Locked" would be a lie
      // (every edit is built and open), "n away" repeats the headline, and
      // earned is already carried by the tick and numeral going dark — so
      // the headline states, the bar shows.
      const _MS_SCALE = 20;
      // Piecewise through the tick positions so the fill meets each tick
      // exactly at its milestone count (a straight n/_MS_SCALE would underrun
      // the nudged 78% last tick).
      function _msFillPct(n) {
        const pts = [{ at: 0, pos: 0 }].concat(_MS_UNLOCKS, [{ at: _MS_SCALE, pos: 100 }]);
        for (let i = 1; i < pts.length; i++) {
          if (n <= pts[i].at) {
            const a = pts[i - 1], b = pts[i];
            return a.pos + ((n - a.at) / (b.at - a.at)) * (b.pos - a.pos);
          }
        }
        return 100;
      }
      function _msBarHtml(n) {
        _msEnsureCss();
        const pct = Math.min(100, _msFillPct(n));
        const ticks = _MS_UNLOCKS.map(u =>
          '<div class="rb-ms-tick' + (n >= u.at ? ' on' : '') + '" style="left:' + u.pos + '%"></div>'
        ).join('');
        const next = _msNext(n);
        const cols = _MS_UNLOCKS.map(u => {
          const lit = n >= u.at || (next && next.key === u.key);
          return '<div class="rb-ms-col' + (lit ? ' on' : '') + '">' +
            '<span class="rb-ms-at">' + String(u.at).padStart(2, '0') + '</span>' +
            '<span class="rb-ms-lbl">' + u.cap + '</span>' +
          '</div>';
        }).join('');
        return '<div class="rb-ms">' +
          '<div class="rb-ms-track"><div class="rb-ms-fill" style="width:' + pct + '%"></div>' + ticks + '</div>' +
          '<div class="rb-ms-cols">' + cols + '</div>' +
        '</div>';
      }

      // Home module order, by piece count. Below the first unlock there is
      // little to prompt about, so the progress card leads directly under the
      // greeting (FTUE) — from 3 pieces on the prompt leads again, as it does
      // today. The rail travels with the prompt in both; #rb-styled always
      // sits immediately above the tracker, which is where its own mount()
      // puts it, so the two never fight. Idempotent — safe on every sync.
      function _rbFtueOrder(n) {
        const dash = document.getElementById('dash');
        const mast = dash && dash.querySelector('.dash-mast');
        const conc = dash && dash.querySelector('.concierge');
        const trk = document.getElementById('wtrk');
        if (!dash || !mast || !conc || !trk) return;
        const rail = document.getElementById('rb-rail');
        const styled = document.getElementById('rb-styled');
        // FTU simplification (2026-08-18): while the quiet index rows carry
        // home, the modules they demote live INSIDE the rows and are never
        // resequenced at dash level. Zero looks (W01/O1) → styled card +
        // rows; first look (O7) → the prompt leads as a card, then "Your
        // looks", then the remaining hairlines.
        const ftuRows = document.getElementById('rb-ftu-rows');
        if (ftuRows) {
          const firstlook = document.getElementById('rb-firstlook');
          const svc0 = dash.querySelector('.services');
          // 'zero' leads with the styled card; every other posture leads
          // with the prompt (then "Your looks" when it exists). The
          // concierge band closes the sequence — it stands beneath the
          // rows from the first session (load rules 2026-08-19; it is
          // hidden in 'zero' anyway, while the styled card is the hero).
          const seq0 = (ftuRows.getAttribute('data-mode') === 'zero'
            ? [styled, ftuRows, svc0]
            : [conc, firstlook, ftuRows, svc0]).filter(Boolean);
          seq0.forEach((el, i) => {
            const prev = i === 0 ? mast : seq0[i - 1];
            if (prev.nextSibling !== el) dash.insertBefore(el, prev.nextSibling);
          });
          return;
        }
        // The concierge's slot is a RULE now, not an accident of markup
        // order (Annie, 2026-08-18): it follows the prompt and the rail,
        // ahead of the Lookbook and Inspiration rows.
        const svc = dash.querySelector('.services');
        const seq = (n < _MS_UNLOCKS[0].at
          ? [styled, conc, rail, svc]
          : [conc, rail, styled, svc]).filter(Boolean);
        seq.forEach((el, i) => {
          const prev = i === 0 ? mast : seq[i - 1];
          if (prev.nextSibling !== el) dash.insertBefore(el, prev.nextSibling);
        });
      }

      // The concierge stands from the FIRST session (Annie's FTUE testing,
      // 2026-08-19 — supersedes both the 3-piece floor and the FTU-rows
      // stand-down of 2026-08-18): it is the MENU for someone who doesn't
      // know what Robes does, so it must be there before she has anything.
      // The one thing that delays it is "Your piece, styled" holding the
      // screen — one goal at a time: clicking through to See the full looks
      // retires the card and the band stands from then on; no piece filed
      // in onboarding means no card, so the band loads straight away.
      // Once she has created one of each
      // live edit — a daily look and a travel edit (the weekly planner is a
      // coming-soon promo; it rejoins this condition when the track
      // returns) — she knows, and the whole module falls away, all at once,
      // meter and all. Data-driven, so it never comes back while the rows
      // stand. Nothing takes its place: the actions live permanently
      // elsewhere, so home gets shorter rather than backfilled.
      // R5: GENERATED counts — a save is not required. The daily look defers
      // its save (2026-08-13), so generation is flagged per user the moment
      // a fresh result renders; saved rows still count (they also carry the
      // fact across devices, which the local flag cannot).
      function _rbSvcFlags() {
        try { const u = _waUid(); return u ? JSON.parse(localStorage.getItem('rb_svc_done__' + u) || '{}') : {}; } catch (_) { return {}; }
      }
      function _rbSvcComplete(kind) {
        try {
          const u = _waUid(); if (!u) return;
          const f = _rbSvcFlags();
          if (f[kind]) return;
          f[kind] = true;
          localStorage.setItem('rb_svc_done__' + u, JSON.stringify(f));
          // The retirement fires on the next home sync, not mid-render.
        } catch (_) {}
      }
      function _rbConciergeDone() {
        try {
          const f = _rbSvcFlags();
          const t = (typeof snLoad === 'function' ? snLoad() : []).map(i => i && i.type);
          return (f.daily || t.indexOf('daily-look') > -1)
            && (f.travel || t.indexOf('travel-edit') > -1);
        } catch (_) { return false; }
      }
      window.__rbSvcAll = function() { if (window.App && App.showWardrobe) App.showWardrobe(); };
      window.__rbSvcSnap = function() { _wtrkOpenAdd(); };
      // "Robes is learning" merged INTO the concierge (2a): a quiet header
      // meter with ONE job — filing replaces borrowed pieces with her own,
      // the only honest reason to catalogue when access isn't the reward —
      // and a filed-piece RECEIPT row (one thumbnail, always: the most
      // recent piece, never a growing strip that duplicates the Wardrobe
      // tab) closing the module with the one add door.
      function _rbConciergeSync(n) {
        const svc = document.querySelector('.services');
        if (!svc) return;
        if (!document.getElementById('rb-svc-style')) {
          const st = document.createElement('style');
          st.id = 'rb-svc-style';
          st.textContent =
            // ── The tinted band (4a): full-bleed within the shell frame —
            // negative gutters mirror .dash's own padding at each
            // breakpoint, so the inner content stays on the page grid.
            // Exactly ONE band per screen; #F2EEE7 with #E1DACB as its
            // hairline (cream-300 disappears against the tint).
            '.services{--rb-bleed:var(--s6,80px);margin:6px calc(var(--rb-bleed) * -1) 48px;padding:48px var(--rb-bleed);background:#F2EEE7;border-top:1px solid var(--rule,#E7E0CF);border-bottom:1px solid var(--rule,#E7E0CF)}' +
            'body[data-density="compact"] .services{--rb-bleed:36px}' +
            '@media(max-width:920px){.services{--rb-bleed:26px;padding-top:36px;padding-bottom:36px}}' +
            '@media(max-width:560px){.services{--rb-bleed:20px;padding-top:32px;padding-bottom:32px}}' +
            // R1 header on the band: eyebrow ink, the meter beside it, one
            // hairline under the pair. No title line.
            '.services .sec-head{align-items:baseline;flex-wrap:wrap;row-gap:10px;padding-bottom:14px;border-bottom:1px solid var(--rule-mid,#D8CFC0);margin-bottom:24px}' +
            '.services .sec-ey{font-weight:400;color:var(--ink,#202021)}' +
            '#rb-svc-learn{margin-left:auto;display:flex;align-items:center;gap:14px}' +
            '#rb-svc-learn .ey{font-size:10px;font-weight:400;letter-spacing:.24em;text-transform:uppercase;color:var(--ink-faint,#9A9082);white-space:nowrap}' +
            // R6: linear fill, and the rail never animates in place.
            '#rb-svc-learn .bar{width:96px;height:2px;background:#E1DACB;overflow:hidden}' +
            '#rb-svc-learn .bar i{display:block;height:100%;background:var(--ink,#202021)}' +
            '#rb-svc-learn .n{font-size:11px;font-weight:300;color:var(--ink-soft,#6E665C);white-space:nowrap}' +
            '#rb-svc-learn .n b{font-weight:400;color:var(--ink,#202021)}' +
            // Cards on the band (4a): white, 4px, 160px photography with a
            // quiet serif ordinal; status caption over its own hairline;
            // text CTA only — never a filled button (R3).
            '.services .svc{border:1px solid var(--rule,#E7E0CF);border-radius:4px}' +
            '.services .svc:hover{border-color:var(--rule-mid,#D8CFC0)}' +
            '.services .svc-img{aspect-ratio:auto;height:260px}' +
            '.services .svc-num{top:10px;left:12px;font-size:15px;color:rgba(250,248,245,0.86);text-shadow:0 1px 8px rgba(32,32,33,0.35)}' +
            '.services .svc-body{padding:14px 16px;gap:7px}' +
            '.services .svc-title{font-size:22px;margin-bottom:0}' +
            '.services .svc-desc{font-size:12px;line-height:1.5;margin-bottom:0}' +
            '.services .svc-cta{gap:8px;font-size:10px;letter-spacing:.2em}' +
            '.services .svc-cta svg{width:15px;height:15px;stroke-width:1.4}' +
            '.rb-svc-note{font-size:11px;font-weight:300;color:var(--ink-faint,#9A9082);line-height:1.4;margin:0;padding-bottom:11px;border-bottom:1px solid var(--cream-200,#EFE9DC)}' +
            // The filed-piece row (R4): a receipt, not a wardrobe.
            '#rb-svc-filed{display:flex;align-items:center;gap:14px;flex-wrap:wrap;margin-top:24px;padding-top:22px;border-top:1px solid var(--rule-mid,#D8CFC0)}' +
            '#rb-svc-filed .th{flex:none;width:40px;height:50px;border-radius:2px;border:1px solid #E1DACB;overflow:hidden;background:var(--cream-100,#F5F0E8)}' +
            '#rb-svc-filed .th img{width:100%;height:100%;object-fit:cover;display:block}' +
            '#rb-svc-filed .th .mono{width:100%;height:100%;display:flex;align-items:center;justify-content:center;font-family:var(--font-serif,\'Cormorant\',Georgia,serif);font-size:17px;color:var(--ink-faint,#9A9082)}' +
            '#rb-svc-filed .txt{display:flex;flex-direction:column;gap:3px;min-width:0}' +
            '#rb-svc-filed .nm{font-size:12px;font-weight:400;color:var(--ink,#202021)}' +
            '#rb-svc-filed .meta{font-size:9px;font-weight:500;letter-spacing:.2em;text-transform:uppercase;color:var(--ink-faint,#9A9082)}' +
            '#rb-svc-filed .all{background:none;border:none;border-left:1px solid var(--rule-mid,#D8CFC0);padding:4px 0 4px 14px;margin-left:0;font-family:inherit;font-size:12px;font-weight:300;color:var(--ink-soft,#6E665C);cursor:pointer;text-align:left}' +
            '#rb-svc-filed .all span{color:var(--ink,#202021);margin-left:6px}' +
            '#rb-svc-filed .sp{flex:1}' +
            '#rb-svc-filed .note{font-size:12px;font-weight:300;color:var(--ink-faint,#9A9082);white-space:nowrap}' +
            '#rb-svc-filed .cta{flex:none;padding:16px 28px;border:1px solid var(--rule-mid,#D8CFC0);border-radius:2px;background:transparent;font-family:inherit;font-size:10px;font-weight:500;letter-spacing:.2em;text-transform:uppercase;color:var(--ink,#202021);cursor:pointer;transition:all .2s}' +
            '#rb-svc-filed .cta:hover{border-color:var(--ink,#202021);background:rgba(32,32,33,0.02)}' +
            // R1 — one header rule for every section on home: eyebrow left,
            // its one action right, a hairline under the pair.
            '#rb-rail .rb-rail-head{padding-bottom:14px;border-bottom:1px solid var(--rule,#E7E0CF);margin-bottom:16px}' +
            '#rb-rail .rb-rail-ey{font-weight:400;letter-spacing:.24em;color:var(--ink-faint,#9A9082)}' +
            '#rb-sn .rb-sec-head,#rb-insp-row .rb-sec-head{padding-bottom:14px;border-bottom:1px solid var(--rule,#E7E0CF)}' +
            '#rb-sn .rb-sec-ey,#rb-insp-row .rb-sec-ey{font-weight:400;letter-spacing:.24em;color:var(--ink-faint,#9A9082)}' +
            '@media(max-width:767px){' +
              '.services .sec-head{flex-direction:column;align-items:stretch}' +
              '#rb-svc-learn{margin-left:0}#rb-svc-learn .bar{flex:1;width:auto}' +
              '#rb-svc-filed .note{display:none}#rb-svc-filed .cta{flex:1 1 100%;min-height:48px;text-align:center}}';
          document.head.appendChild(st);
        }
        // Header: the eyebrow and the meter carry it — the static
        // "Specialised edits, on request" meta yields its slot.
        const head = svc.querySelector('.sec-head');
        if (head) {
          const meta = head.querySelector('.sec-meta');
          if (meta) meta.remove();
          let learn = document.getElementById('rb-svc-learn');
          if (!learn) {
            learn = document.createElement('div');
            learn.id = 'rb-svc-learn';
            head.appendChild(learn);
          }
          // R6: fill = min(pieces / 15, 1) — the milestone ladder described
          // gates, and there are none. Bare count, never a denominator.
          const pct = Math.min(100, Math.round((n / _WA_TARGET) * 1000) / 10);
          learn.innerHTML = '<span class="ey">Robes is learning</span>' +
            '<span class="bar"><i style="width:' + pct + '%"></i></span>' +
            '<span class="n"><b>' + n + '</b> piece' + (n === 1 ? '' : 's') + ' filed</span>';
        }
        // The filed-piece row — a receipt, not a wardrobe: one thumbnail,
        // fixed height, the CTA never pushed off the row.
        let row = document.getElementById('rb-svc-filed');
        if (!row) {
          row = document.createElement('div');
          row.id = 'rb-svc-filed';
          svc.appendChild(row);
        }
        const it = _waItems[0] || null;
        const receipt = it
          ? '<span class="th">' + (it.image_url
              ? '<img src="' + _waEsc(it.image_url) + '" alt="">'
              : '<span class="mono">' + _waEsc((it.label || '?').charAt(0).toUpperCase()) + '</span>') + '</span>' +
            '<span class="txt"><span class="nm">' + _waEsc(it.label || 'A piece') + '</span>' +
            '<span class="meta">' + _waEsc(it.category || 'Piece') + ' · ' + (n === 1 ? 'Your first filed piece' : 'Last filed') + '</span></span>'
          : '';
        const all = n >= 2
          ? '<button type="button" class="all" onclick="window.__rbSvcAll()">' + n + ' pieces in your wardrobe ·<span>See all →</span></button>'
          : '';
        row.innerHTML = receipt + all + '<span class="sp"></span>' +
          '<span class="note">One photo files four pieces.</span>' +
          '<button type="button" class="cta" onclick="window.__rbSvcSnap()">Catalogue what you’re wearing now</button>';
      }
      function _rbGateConcierge(n) {
        const svc = document.querySelector('.services');
        if (!svc) return;
        // Load rules (Annie, 2026-08-19): the band shows from the first
        // session at any piece count — even beneath the FTU index rows —
        // and only waits while "Your piece, styled" is the hero (the
        // click through to the full looks retires the card, which is what
        // brings the band in). Once she has made one of each live edit
        // the module retires for good (2a).
        const show = !document.getElementById('rb-styled') && !_rbConciergeDone();
        svc.style.display = show ? '' : 'none';
        if (show) {
          _rbConciergeSync(n);
          if (typeof _rbUpdateDailyOutfitLock === 'function') _rbUpdateDailyOutfitLock();
        }
      }

      // Programmatic edit-by-id (the tracker's tiles once used it; the
      // harnesses still do). The grid card itself opens the piece PAGE now.
      window.__wtrkEdit = function(id) {
        const it = _waItems.find(w => String(w.id) === String(id));
        if (it) _waOpenEdit(it);
      };
      function _wtrkOpenAdd() {
        _waEditId = null;
        _waAfterAdd = null;
        if (window.WA && WA.open) WA.open();
      }
      function _waSyncCounts() {
        const n = _waItems.length;
        const label = n + ' piece' + (n !== 1 ? 's' : '');

        // Audit X.1 — the typewriter demos with HER wardrobe, not the
        // Balmain fallback piece: once anything is filed, the rotating
        // examples lead with her most recent pieces (the bundle's
        // twList() reads window.__rbPromptExamples lazily each cycle).
        try {
          const named = _waItems.filter(i => i.label && i.label.length <= 34);
          if (named.length) {
            const ex = ['Style my ' + named[0].label.toLowerCase() + ' three ways'];
            if (named.length > 1) ex.push('An outfit around my ' + named[1].label.toLowerCase() + ' for the weekend');
            ex.push('What should I wear to dinner in the city tonight?');
            ex.push('Help me pack for a weekend away');
            window.__rbPromptExamples = ex;
          }
        } catch (_) {}

        if (!document.getElementById('rb-wtrk-style')) {
          const st = document.createElement('style');
          st.id = 'rb-wtrk-style';
          st.textContent =
            '.wtrk-star{position:absolute;top:5px;right:5px;width:18px;height:18px;border-radius:100px;background:var(--ink,#202021);display:flex;align-items:center;justify-content:center;z-index:2;pointer-events:none}' +
            '.wtrk-star svg{width:9px;height:9px;display:block}' +
            // Demoted register (Annie, 2026-08-18): the learning card is the
            // page's LAST module — smaller, more compact, and off the sage
            // wash onto the app's white-card language (rose eyebrow like
            // every other home section).
            '.tracker{margin-bottom:44px}' +
            '.wtrk-ey{color:var(--rose,#8E7077)}' +
            '.wtrk-card{background:#fff;padding:16px 20px 14px}' +
            '.wtrk-toprow{gap:18px;align-items:center}' +
            '.wtrk-head{font-size:16.5px}' +
            '.wtrk-num{font-size:30px}' +
            '.wtrk-num .wtrk-num-lbl{margin-top:5px}' +
            '.wtrk-ms{margin:10px 0 12px}' +
            '.wtrk-it,.wtrk-add{flex:0 0 66px;height:88px}' +
            '.wtrk-it-scrim{padding:18px 6px 6px}' +
            '.wtrk-it-name{font-size:9px}' +
            '.wtrk-mono{font-size:20px}' +
            '.wtrk-cta{padding:9px 16px}' +
            '.wtrk-fastrow{margin-top:12px}' +
            '.wtrk-snap{padding:8px 15px}';
          document.head.appendChild(st);
        }

        // wg-count pill inside the wardrobe panel (wishlist view owns the
        // count label while it's active — see _waV2Sync)
        const countEl = document.getElementById('wg-count');
        if (countEl && _waView !== 'wishlist') countEl.textContent = label;

        // nav badge
        const navBadge = document.querySelector('.nav-wbtn-count');
        if (navBadge) navBadge.textContent = n;

        // dashboard tracker: derived headline + milestone bar + the
        // catalogued pieces themselves, so the wardrobe is visible on the
        // dashboard, not just counted
        _msTrack(n);
        const numEl = document.getElementById('wtrk-num');
        const headEl = document.getElementById('wtrk-head');
        const msEl = document.getElementById('wtrk-ms');
        // MERGED (2a, 2026-08-18): "Robes is learning" lives inside the
        // Styling Concierge now — a header meter + the filed-piece receipt
        // row. The standalone card never renders again; the section stays
        // in the DOM only as _rbApplyLayout's anchor (and its internals
        // keep painting, invisibly, so nothing downstream breaks).
        const trkSection = document.getElementById('wtrk');
        if (trkSection) trkSection.style.display = 'none';
        // Bare count, no denominator — "n / 15" read as the wardrobe's item
        // limit (Clodagh test 2026-07-29). Never reintroduce a fraction here.
        if (numEl) numEl.innerHTML = n + '<span class="wtrk-num-lbl">Piece' + (n === 1 ? '' : 's') + ' filed</span>';
        if (headEl) headEl.innerHTML = _msHeadline(n);
        if (msEl) msEl.innerHTML = _msBarHtml(n);

        const itemsEl = document.getElementById('wtrk-items');
        if (itemsEl) {
          // Hero pieces lead the strip (starred badge) while the tracker is
          // still on the page (<15 items) — the rest keep newest-first order
          const ordered = _waItems.slice().sort((a, b) => {
            const ah = a.hero_position != null, bh = b.hero_position != null;
            if (ah !== bh) return ah ? -1 : 1;
            return ah ? (a.hero_position || 0) - (b.hero_position || 0) : 0;
          });
          const tiles = ordered.slice(0, 12).map(it => {
            const idAttr = _waEsc(String(it.id));
            return '<button class="wtrk-it" onclick="window.__wtrkEdit(\'' + idAttr + '\')" title="' + _waEsc(it.label) + '">' +
              (it.image_url
                ? '<img src="' + _waEsc(it.image_url) + '" alt="" loading="lazy">'
                : '<div class="wtrk-mono">' + _waEsc((it.label || '?').charAt(0).toUpperCase()) + '</div>') +
              (it.hero_position != null ? '<span class="wtrk-star">' + _waStarSvg(true) + '</span>' : '') +
              '<div class="wtrk-it-scrim"><div class="wtrk-it-name">' + _waEsc(it.label) + '</div>' +
              (it.category ? '<div class="wtrk-it-cat">' + _waEsc(it.category) + '</div>' : '') + '</div></button>';
          }).join('');
          const more = n > 12
            ? '<button class="wtrk-add" style="border-style:solid" onclick="window.App&&App.showWardrobe&&App.showWardrobe()"><span>+' + (n - 12) + ' more</span></button>'
            : '';
          itemsEl.innerHTML = tiles + more +
            '<button class="wtrk-add" id="wtrk-add-tile"><svg viewBox="0 0 24 24"><line x1="12" y1="5" x2="12" y2="19"></line><line x1="5" y1="12" x2="19" y2="12"></line></svg><span>Add</span></button>';
          const addTile = document.getElementById('wtrk-add-tile');
          if (addTile) addTile.onclick = _wtrkOpenAdd;
        }

        const ctaEl = document.getElementById('wtrk-cta');
        if (ctaEl) {
          ctaEl.childNodes[0].textContent = n === 0 ? 'Add your first pieces' : 'Add pieces';
          ctaEl.onclick = function(e) { e.preventDefault(); e.stopPropagation(); _wtrkOpenAdd(); };
        }
        const snapEl = document.getElementById('wtrk-snap');
        if (snapEl) snapEl.onclick = _wtrkOpenAdd;

        // Refresh the masthead — once the count lands, the returner echo shows
        // the real number (and an established ≥3-piece closet flips a first
        // load to the returner register).
        if (typeof _rbUpdateMasthead === 'function') _rbUpdateMasthead();
        _rbFtueOrder(n);
        _rbGateConcierge(n);
        // FTUE step 3 (2026-08-12): at zero looks the inline rack replaces
        // the learning card outright — home shows no bar at zero.
        if (typeof _lkHomeSync === 'function') _lkHomeSync();
        if (typeof _rbSilPrompt === 'function') _rbSilPrompt();
      }

      // ── Pack-for-a-trip multi-select (wardrobe-first PRD: the connection
      // to packing lives inside the wardrobe too) ────────────────────────
      let _wgPackMode = false;
      let _wgPackSel = [];

      function _wgDecorate(div, on) {
        div.style.outline = on ? '2px solid #202021' : '';
        div.style.outlineOffset = on ? '-2px' : '';
        let chk = div.querySelector('.wg-pack-chk');
        if (on && !chk) {
          chk = document.createElement('span');
          chk.className = 'wg-pack-chk';
          chk.style.cssText = 'position:absolute;top:8px;right:8px;width:20px;height:20px;border-radius:50%;background:#202021;color:#fff;font-size:11px;display:flex;align-items:center;justify-content:center;z-index:2;line-height:1;pointer-events:none';
          chk.textContent = '✓';
          const wrap = div.querySelector('.wg-img-wrap') || div;
          wrap.style.position = 'relative';
          wrap.appendChild(chk);
        } else if (!on && chk) chk.remove();
      }

      function _wgPackBar() {
        let bar = document.getElementById('wg-packbar');
        if (!_wgPackMode) { if (bar) bar.remove(); return; }
        if (!bar) {
          bar = document.createElement('div');
          bar.id = 'wg-packbar';
          bar.style.cssText = 'position:fixed;bottom:22px;left:50%;transform:translateX(-50%);z-index:60;display:flex;gap:10px;align-items:center;background:#202021;border-radius:100px;padding:10px 12px 10px 22px;box-shadow:0 12px 32px -8px rgba(32,32,33,0.45);max-width:calc(100vw - 32px);box-sizing:border-box;flex-wrap:wrap;justify-content:center';
          document.body.appendChild(bar);
        }
        const n = _wgPackSel.length;
        bar.innerHTML = '<span style="font-size:12px;color:#fff;letter-spacing:.04em;white-space:nowrap">' +
          (n ? n + ' piece' + (n === 1 ? '' : 's') + ' selected' : 'Tap everything you’re tempted to bring') + '</span>' +
          '<button onclick="window.__wgPackGo()"' + (n < 2 ? ' disabled' : '') + ' style="padding:9px 18px;border:none;border-radius:100px;background:#fff;color:#202021;font-size:11px;font-weight:500;letter-spacing:.08em;text-transform:uppercase;cursor:' + (n < 2 ? 'default' : 'pointer') + ';opacity:' + (n < 2 ? '.5' : '1') + '">Pack for a trip →</button>' +
          '<button onclick="window.__wgPackCancel()" style="padding:9px 12px;border:none;border-radius:100px;background:none;color:rgba(255,255,255,0.72);font-size:11px;cursor:pointer">Cancel</button>';
      }

      window.__wgPackStart = function() {
        _wgPackMode = true;
        _wgPackSel = [];
        _waRender();
        _wgPackBar();
      };
      window.__wgPackCancel = function() {
        _wgPackMode = false;
        _wgPackSel = [];
        _waRender();
        _wgPackBar();
      };
      window.__wgPackGo = function() {
        if (_wgPackSel.length < 2) return;
        const sel = _wgPackSel.slice();
        window.__wgPackCancel();
        // drop the wardrobe overlay so the brief modal lands on the dashboard
        const wp = document.querySelector('.wardrobe-panel');
        if (wp && wp.classList.contains('visible')) {
          const wbtnCount = document.querySelector('.nav-wbtn-count');
          const wbtn = wbtnCount ? wbtnCount.closest('button') : null;
          if (wbtn) wbtn.click(); else wp.classList.remove('visible');
        }
        window.__tvOpen({ anchors: sel });
      };

      // Any path that closes the wardrobe panel also ends select mode —
      // otherwise the floating pack bar outlives the grid it selects from.
      (function _wgWatchPanel() {
        const wp = document.querySelector('.wardrobe-panel');
        if (!wp) { setTimeout(_wgWatchPanel, 500); return; }
        new MutationObserver(function() {
          if (!wp.classList.contains('visible') && _wgPackMode) window.__wgPackCancel();
        }).observe(wp, { attributes: true, attributeFilter: ['class'] });
      })();

      function _waCard(it) {
        const div = document.createElement('div');
        div.className = 'wg-item';
        const meta = [it.brand, it.times_worn > 0 ? it.times_worn + '\xd7 worn' : null].filter(Boolean).join(' \xb7 ');
        // Star = feature on the Hero Rack (hidden in pack mode — the pack
        // check occupies the same corner)
        const isHero = it.hero_position != null;
        const star = _wgPackMode ? '' :
          '<button class="rb-star' + (isHero ? ' on' : '') + '" title="' + (isHero ? 'Remove from Hero Rack' : 'Feature in Hero Rack') + '" onclick="event.stopPropagation();window.__waHeroToggle(\'' + _waEsc(String(it.id)) + '\')">' + _waStarSvg(isHero) + '</button>';
        div.innerHTML = '<div class="wg-img-wrap">' +
          (it.image_url ? '<img src="' + _waEsc(it.image_url) + '" alt="' + _waEsc(it.label) + '" loading="lazy">' :
            '<div style="width:100%;height:100%;display:flex;align-items:center;justify-content:center;opacity:.3"><svg viewBox="0 0 24 24" width="28" height="28" fill="none" stroke="currentColor" stroke-width="1.2"><rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8.5" cy="8.5" r="1.5"/><polyline points="21 15 16 10 5 21"/></svg></div>') +
          (it.times_worn === 0 ? '<div class="wg-owned-badge">Never worn</div>' : '') +
          star +
          '</div><div class="wg-info"><div class="wg-name">' + _waEsc(it.label) + '</div>' +
          (meta ? '<div class="wg-metar">' + _waEsc(meta) + '</div>' : '') + '</div>';
        if (_wgPackMode) _wgDecorate(div, _wgPackSel.indexOf(String(it.id)) !== -1);
        div.addEventListener('click', () => {
          if (_wgPackMode) {
            const id = String(it.id);
            const i = _wgPackSel.indexOf(id);
            if (i === -1) _wgPackSel.push(id); else _wgPackSel.splice(i, 1);
            _wgDecorate(div, i === -1);
            _wgPackBar();
            return;
          }
          // The card opens the PIECE (Robes_Piece_IA, 2026-09-07) — the
          // editor is the pencil on that page, one door in from here.
          window.__rbPieceOpen(it.id, { from: 'wardrobe' });
        });
        return div;
      }

      function _waAddCard() {
        // Amplified entry card (was a bare `+`): the engine room of the
        // product deserves weight — and it sells the roadmap doors too.
        const div = document.createElement('div');
        div.className = 'wg-item rb-add-card';
        div.innerHTML = '<span class="rb-add-plus">+</span>' +
          '<span class="rb-add-serif">Add a piece</span>' +
          '<span class="rb-add-hint">Photograph \xb7 Link \xb7 Without a photo</span>';
        div.addEventListener('click', () => window.__waAddChooser());
        return div;
      }

      // The tab row holds the top TEN sheet categories by piece count —
      // membership by count, display in the sheet's canonical order — with
      // the remainder behind one "More ▾" popover, so the row never wraps
      // to a second line (Annie, 2026-08-13). At zero pieces the first ten
      // canonical categories stand in; an active category never hides —
      // picked from More, it surfaces into the row.
      var _waMoreCats = [];
      function _waTabCounts() {
        const counts = {};
        _waItems.forEach(it => { const c = _waSheetCatOf(it) || 'Other'; counts[c] = (counts[c] || 0) + 1; });
        return counts;
      }
      function _waTabsPaint() {
        const container = document.getElementById('wg-filters');
        if (!container) return;
        // An open cascade lives inside this container — never repaint under
        // it (the tab tap that closes it repaints on its way through).
        if (container.querySelector('#rb-wg-cascade')) return;
        document.getElementById('rb-wg-morepop')?.remove();
        const counts = _waTabCounts();
        const pool = _WA_TAB_CATS.filter(c => c !== 'All');
        const top = pool.map((c, i) => ({ c, n: counts[c] || 0, i }))
          .sort((a, b) => b.n - a.n || a.i - b.i)
          .slice(0, 10).map(x => x.c);
        const visible = pool.filter(c => top.indexOf(c) > -1 || c === _waCat);
        _waMoreCats = pool.filter(c => visible.indexOf(c) < 0);
        container.innerHTML = '';
        // Light text tabs — the taxonomy sheet's L1 categories. A tab whose
        // category carries subcategories opens the Subcategory › Item type
        // cascade (redesign 2026-08-05): the browse drill reads the SAME
        // taxonomy tree the add/edit pickers do — one source of truth.
        ['All'].concat(visible).forEach(cat => {
          const btn = document.createElement('button');
          btn.className = 'wg-tab' + (cat === _waCat ? ' active' : '');
          btn.dataset.cat = cat;
          btn.textContent = cat;
          btn.addEventListener('click', () => window.__waCatTap(cat));
          container.appendChild(btn);
        });
        if (_waMoreCats.length) {
          const more = document.createElement('button');
          more.className = 'wg-tab';
          more.id = 'rb-wg-moretab';
          more.textContent = 'More ▾';
          more.addEventListener('click', e => window.__waMoreTap(e));
          container.appendChild(more);
        }
      }
      window.__waMoreTap = function(e) {
        if (e && e.stopPropagation) e.stopPropagation();
        const old = document.getElementById('rb-wg-morepop');
        if (old) { old.remove(); return; }
        const btn = document.getElementById('rb-wg-moretab');
        if (!btn || !_waMoreCats.length) return;
        const r = btn.getBoundingClientRect();
        const counts = _waTabCounts();
        const pop = document.createElement('div');
        pop.id = 'rb-wg-morepop';
        pop.style.cssText = 'position:fixed;z-index:990;top:' + Math.round(r.bottom + 6) + 'px;left:' +
          Math.round(Math.max(12, Math.min(r.left, window.innerWidth - 244))) +
          'px;background:#fff;border:0.5px solid var(--rule-mid);border-radius:var(--rad);box-shadow:0 14px 36px -10px rgba(32,32,33,0.2);padding:6px;min-width:220px;max-height:60vh;overflow-y:auto';
        pop.innerHTML = _waMoreCats.map(c =>
          '<button data-cat="' + _waEsc(c) + '" style="display:flex;align-items:center;justify-content:space-between;gap:14px;width:100%;border:none;background:none;padding:9px 12px;border-radius:8px;font-family:inherit;font-size:12.5px;color:var(--ink);cursor:pointer;text-align:left">' +
            '<span>' + _waEsc(c) + '</span>' +
            (counts[c] ? '<span style="font-size:10.5px;color:var(--ink-faint)">' + counts[c] + '</span>' : '') +
          '</button>').join('');
        pop.addEventListener('click', ev => {
          const b = ev.target.closest('button[data-cat]');
          if (!b) return;
          pop.remove();
          window.__waCatTap(b.dataset.cat);
        });
        document.body.appendChild(pop);
        setTimeout(() => {
          const dismiss = ev => {
            if (!pop.contains(ev.target)) { pop.remove(); document.removeEventListener('click', dismiss); }
          };
          document.addEventListener('click', dismiss);
        }, 0);
      };

      let _waFiltersBuilt = false;
      function _waBuildFilters() {
        const container = document.getElementById('wg-filters');
        if (!container) return;
        // Only rebuild if the bundle has overwritten our tabs (its mock pills
        // carry no .wg-tab class, so their write leaves none behind)
        const existing = container.querySelector('.wg-tab');
        if (_waFiltersBuilt && existing) { _waTrailSync(); return; }
        _waFiltersBuilt = true;
        _waTabsPaint();
        // The trail row below the tabs: breadcrumb + live count on the left,
        // Add piece + Refine on the right (the mobile FAB and the wardrobe
        // Pack-a-trip pill retired with this layout — packing lives in the
        // travel intake).
        if (!document.getElementById('rb-wg-trail')) {
          const trail = document.createElement('div');
          trail.id = 'rb-wg-trail';
          trail.innerHTML = '<div id="rb-wg-crumbs" class="rb-wg-crumbs"></div>' +
            '<div class="rb-wg-trailbtns">' +
              '<button class="wg-pill rb-add-pill" id="rb-add-pill">+ Add piece</button>' +
              '<button class="wg-pill rb-refine-pill" id="rb-refine-pill">Refine</button>' +
            '</div>';
          container.parentNode.insertBefore(trail, container.nextSibling);
          trail.querySelector('#rb-add-pill').addEventListener('click', () => {
            if (_waView === 'wishlist') window.__wlOpenAdd();
            else window.__waAddChooser();
          });
          trail.querySelector('#rb-refine-pill').addEventListener('click', () => window.__waRefToggle());
        }
        _waRefinePillSync();
        _waTrailSync();
      }

      // Tab tap: switch category; a category with subcategories also opens
      // its cascade (second tap on the active tab toggles it).
      window.__waCatTap = function(cat) {
        const drillable = cat !== 'All' && cat !== 'Other' && !!_waTaxTree && _waTaxL2s(cat).length > 0;
        if (_waCat === cat && drillable) {
          if (document.getElementById('rb-wg-cascade')) _waCascadeClose();
          else _waCascadeOpen(cat);
          return;
        }
        _waCat = cat;
        _waDrill = { l2: '', l3: '' };
        document.querySelectorAll('#wg-filters .wg-tab').forEach(p => p.classList.toggle('active', p.dataset.cat === cat));
        _waRender();
        if (drillable) _waCascadeOpen(cat); else _waCascadeClose();
      };

      // ── The category cascade (screens 01 / 09) ────────────────────────
      // Desktop: a two-column flyout under the active tab (Subcategory ›
      // Item type). Mobile (≤767px): a bottom sheet that drills one level
      // at a time. Picking filters the grid live; "All {…}" rows clear the
      // level; outside tap or ✕ closes.
      var _casL2 = ''; // the L2 whose item types are listed (col 2 / level 2)
      function _waCascadeClose() {
        document.getElementById('rb-wg-cascade')?.remove();
        document.removeEventListener('pointerdown', _waCascadeOutside, true);
      }
      function _waCascadeOutside(e) {
        const c = document.getElementById('rb-wg-cascade');
        if (!c) { _waCascadeClose(); return; }
        const tabs = document.getElementById('wg-filters');
        if (!c.contains(e.target) && !(tabs && tabs.contains(e.target))) _waCascadeClose();
      }
      function _waCascadeOpen(cat) {
        _waCascadeClose();
        _casL2 = _waDrill.l2 || '';
        const wrap = document.createElement('div');
        wrap.id = 'rb-wg-cascade';
        const mobile = window.matchMedia('(max-width: 767px)').matches;
        wrap.className = 'rb-wg-cas' + (mobile ? ' sheet' : '');
        if (mobile) {
          document.body.appendChild(wrap);
        } else {
          const container = document.getElementById('wg-filters');
          if (!container) return;
          container.style.position = 'relative';
          const tab = Array.prototype.find.call(container.querySelectorAll('.wg-tab'), t => t.dataset.cat === cat);
          wrap.style.left = Math.max(0, tab ? tab.offsetLeft : 0) + 'px';
          container.appendChild(wrap);
        }
        _waCascadePaint();
        setTimeout(function() { document.addEventListener('pointerdown', _waCascadeOutside, true); }, 0);
      }
      function _waCascadePaint() {
        const wrap = document.getElementById('rb-wg-cascade');
        if (!wrap) return;
        const cat = _waCat;
        const l2s = _waTaxL2s(cat);
        const mobile = wrap.classList.contains('sheet');
        const esc = _waEsc;
        if (mobile) {
          if (!_casL2) {
            wrap.innerHTML = '<div class="cas-hd"><span class="cas-title">' + esc(cat) + '</span><button class="cas-x" data-act="close">✕</button></div>' +
              '<div class="cas-ey">Subcategory</div>' +
              '<div class="cas-list">' +
                '<button class="cas-row all" data-act="all-cat">All ' + esc(cat.toLowerCase()) + '</button>' +
                l2s.map(v => '<button class="cas-row" data-act="l2" data-v="' + esc(v) + '"><span>' + esc(v) + '</span><span class="mk">›</span></button>').join('') +
              '</div>';
          } else {
            const l3s = _waTaxL3s(_casL2);
            wrap.innerHTML = '<div class="cas-hd"><button class="cas-back" data-act="back">‹ ' + esc(cat) + '</button><button class="cas-x" data-act="close">✕</button></div>' +
              '<div class="cas-title" style="margin:2px 0 8px">' + esc(_casL2) + '</div>' +
              '<div class="cas-ey">Item type</div>' +
              '<div class="cas-list">' +
                '<button class="cas-row all' + (_waDrill.l2 === _casL2 && !_waDrill.l3 ? ' sel' : '') + '" data-act="all-l2">All ' + esc(_casL2.toLowerCase()) + '</button>' +
                l3s.map(v => '<button class="cas-row' + (_waDrill.l3 === v ? ' sel' : '') + '" data-act="l3" data-v="' + esc(v) + '"><span>' + esc(v) + '</span>' + (_waDrill.l3 === v ? '<span class="mk">✓</span>' : '') + '</button>').join('') +
              '</div>';
          }
        } else {
          const col1 = '<div class="cas-col c1"><div class="cas-ey">Subcategory</div>' +
            '<button class="cas-row all' + (!_waDrill.l2 ? ' sel' : '') + '" data-act="all-cat">All ' + esc(cat.toLowerCase()) + '</button>' +
            l2s.map(v => '<button class="cas-row' + (_casL2 === v ? ' sel' : '') + '" data-act="l2" data-v="' + esc(v) + '"><span>' + esc(v) + '</span><span class="mk">›</span></button>').join('') +
            '</div>';
          const col2 = _casL2
            ? '<div class="cas-col c2"><div class="cas-ey">Item type</div>' +
              '<button class="cas-row all' + (_waDrill.l2 === _casL2 && !_waDrill.l3 ? ' sel' : '') + '" data-act="all-l2">All ' + esc(_casL2.toLowerCase()) + '</button>' +
              _waTaxL3s(_casL2).map(v => '<button class="cas-row' + (_waDrill.l3 === v ? ' sel' : '') + '" data-act="l3" data-v="' + esc(v) + '"><span>' + esc(v) + '</span>' + (_waDrill.l3 === v ? '<span class="mk">✓</span>' : '') + '</button>').join('') +
              '</div>'
            : '';
          wrap.innerHTML = col1 + col2;
        }
        if (!wrap.dataset.wired) {
          wrap.dataset.wired = '1';
          wrap.addEventListener('click', function(e) {
            const b = e.target.closest('[data-act]');
            if (!b) return;
            const act = b.dataset.act;
            if (act === 'close') { _waCascadeClose(); return; }
            if (act === 'back') { _casL2 = ''; _waCascadePaint(); return; }
            if (act === 'all-cat') {
              _waDrill = { l2: '', l3: '' };
              _casL2 = '';
              _waRender();
              _waCascadeClose();
              return;
            }
            // Every pick applies the filter immediately; the mobile sheet
            // also CLOSES on pick (beta feedback 2026-08-05 — tap, filter,
            // done; reopening the tab's cascade lands on the item types of
            // the drilled subcategory, with ‹ back for the level above).
            // Desktop keeps the flyout open on an L2 pick so the item-type
            // column can follow.
            if (act === 'l2') {
              _casL2 = b.dataset.v;
              _waDrill = { l2: b.dataset.v, l3: '' };
              _waRender();
              if (wrap.classList.contains('sheet')) _waCascadeClose();
              else _waCascadePaint();
              return;
            }
            if (act === 'all-l2') {
              _waDrill = { l2: _casL2, l3: '' };
              _waRender();
              _waCascadeClose();
              return;
            }
            if (act === 'l3') {
              _waDrill = { l2: _casL2, l3: b.dataset.v };
              _waRender();
              _waCascadeClose();
            }
          });
        }
      }

      // The breadcrumb trail — "Robes › Bottoms › Jeans › Barrel-leg jeans
      // ✕ · 4 pieces". The ✕ clears the whole category trail (tab back to
      // All); Refine picks survive it.
      window.__waTrailClear = function() {
        _waCat = 'All';
        _waDrill = { l2: '', l3: '' };
        document.querySelectorAll('#wg-filters .wg-tab').forEach(p => p.classList.toggle('active', p.dataset.cat === 'All'));
        _waCascadeClose();
        _waRender();
      };
      function _waTrailSync() {
        const crumbs = document.getElementById('rb-wg-crumbs');
        if (!crumbs) return;
        const n = _waFilteredItems().length;
        const countHtml = '<span class="rb-wg-trailcount">' + n + ' piece' + (n === 1 ? '' : 's') + '</span>';
        if (_waCat === 'All') { crumbs.innerHTML = countHtml; return; }
        const path = [_waCat].concat(_waDrill.l2 ? [_waDrill.l2] : []).concat(_waDrill.l3 ? [_waDrill.l3] : []);
        crumbs.innerHTML = '<span class="rb-wg-crumb-mark">Robes</span>' +
          path.map((p, i) => '<span class="rb-wg-crumb-sep">›</span><span class="rb-wg-crumb' + (i === path.length - 1 ? ' cur' : '') + '">' + _waEsc(p) + '</span>').join('') +
          '<button class="rb-wg-trailx" onclick="window.__waTrailClear()" title="Clear">✕</button>' +
          countHtml;
      }

      function _waOpenEdit(it) {
        _waEditId = it.id;
        if (!window.WA) return;
        // The patched WA.open's edit branch renders the shared add/edit
        // form prefilled from the row (redesign 2026-08-05) — nothing to
        // populate here any more.
        WA.open();
      }

      // Patch WA.submit — keep all other WA methods untouched
      const _origWAClose = () => window.WA && WA.close();
      const _origWASubmit = window.WA && WA.submit;

      // 3-step wardrobe add flow: (1) our photo-capture UI, (2) Reading…, (3) Here's what Robes saw.
      // We own all 3 steps — replace .fm-step on WA.open, use our own file input.
      (function _waSetupAutoTag() {
        let _photoDataUrl = '';
        let _origStepHTML = '';

        if (!document.getElementById('wa-spin-style')) {
          const st = document.createElement('style'); st.id = 'wa-spin-style';
          st.textContent = [
            '@keyframes wa-spin{to{transform:rotate(360deg)}}',
            '@keyframes rb-scan-line{0%{top:0%;opacity:1}80%{top:100%;opacity:1}81%{top:0%;opacity:0}100%{top:0%;opacity:1}}',
            '@keyframes rb-scan-glow{0%,100%{opacity:.7}50%{opacity:1}}',
          ].join('');
          document.head.appendChild(st);
        }

        // ── Shared pickers (add/edit redesign 2026-08-05) ────────────────
        // One floating panel serves the Category / Subcategory / Item type
        // fields (custom lists — never a native OS dropdown) and the colour
        // Change popover. Desktop: anchored panel under the field; ≤767px:
        // a bottom sheet. Closes on outside pointerdown.
        function _waPopClose() {
          document.getElementById('rb-wa-pop')?.remove();
          document.removeEventListener('pointerdown', _waPopOutside, true);
        }
        window.__waPopClose = _waPopClose;
        function _waPopOutside(e) {
          const pop = document.getElementById('rb-wa-pop');
          if (pop && !pop.contains(e.target)) _waPopClose();
        }
        function _waPopShell(anchor, html) {
          _waPopClose();
          const pop = document.createElement('div');
          pop.id = 'rb-wa-pop';
          pop.className = 'rb-wapop';
          pop.innerHTML = html;
          document.body.appendChild(pop);
          const mobile = window.matchMedia('(max-width: 767px)').matches;
          if (mobile || !anchor) {
            pop.classList.add('sheet');
          } else {
            const r = anchor.getBoundingClientRect();
            const w = Math.max(250, Math.min(330, Math.round(r.width)));
            pop.style.width = w + 'px';
            pop.style.left = Math.max(8, Math.min(r.left, window.innerWidth - w - 12)) + 'px';
            const top = r.bottom + 6;
            pop.style.top = top + 'px';
            pop.style.maxHeight = Math.max(200, Math.min(360, window.innerHeight - top - 14)) + 'px';
          }
          setTimeout(function() { document.addEventListener('pointerdown', _waPopOutside, true); }, 0);
          return pop;
        }
        function _waPopRows(title, rows) {
          return '<div class="rb-wapop-hd"><span>' + _waEsc(title) + '</span><button type="button" class="rb-wapop-x" onclick="window.__waPopClose()">✕</button></div>' +
            '<div class="rb-wapop-list">' + rows.map(function(r) {
              return '<button type="button" class="rb-wapop-row' + (r.sel ? ' sel' : '') + (r.muted ? ' muted' : '') + '" data-v="' + _waEsc(r.value) + '">' +
                '<span>' + _waEsc(r.label) + '</span>' + (r.sel ? '<span class="rb-wapop-chk">✓</span>' : '') + '</button>';
            }).join('') + '</div>';
        }

        // Category / Subcategory / Item type field pickers. Attributes are
        // category-scoped: the L2 list only ever holds the selected sheet
        // L1's subcategories, L3 only the selected L2's item types.
        window.__waFieldPick = function(kind, el) {
          const s = window.__waSawTaxSel;
          const treeOn = !!_waTaxTree;
          let title, rows, onPick;
          if (kind === 'cat') {
            title = 'Category';
            const list = treeOn ? _WA_SHEET_CATS.concat(['Other']) : WA_CATS.slice(1);
            const cur = treeOn ? (s && s.sheet) : window.__waSawCat;
            rows = list.map(function(c) { return { label: c, value: c, sel: c === cur }; });
            onPick = function(v) {
              if (treeOn) window.__waTaxCatChange(v);
              else { window.__waSawCat = v; if (window.__waFormRepaint) window.__waFormRepaint(); }
            };
          } else if (kind === 'l2') {
            if (!treeOn || !s || !s.sheet) return;
            title = 'Subcategory';
            rows = [{ label: 'Not sure', value: '', sel: !s.l2, muted: true }]
              .concat(_waTaxL2s(s.sheet).map(function(v) { return { label: v, value: v, sel: v === s.l2 }; }));
            onPick = function(v) { window.__waTaxL2Change(v); };
          } else {
            if (!treeOn || !s || !s.l2) return;
            title = 'Item type';
            rows = [{ label: 'Not sure', value: '', sel: !s.l3, muted: true }]
              .concat(_waTaxL3s(s.l2).map(function(v) { return { label: v, value: v, sel: v === s.l3 }; }));
            onPick = function(v) { window.__waTaxL3Change(v); };
          }
          const pop = _waPopShell(el, _waPopRows(title, rows));
          pop.querySelector('.rb-wapop-list').addEventListener('click', function(e) {
            const b = e.target.closest('.rb-wapop-row');
            if (!b) return;
            _waPopClose();
            onPick(b.dataset.v);
          });
        };

        // Colour is a single swatch with a quiet Change affordance — the
        // palette is a popover, not a wall (design screen 07).
        window.__waColourPop = function(el) {
          const grid = _ALL_SWATCHES.map(function(sw) {
            return '<button type="button" class="rb-wapop-sw' + (window.__waSawColor === sw.name ? ' sel' : '') + '" title="' + _waEsc(sw.name) + '" aria-label="' + _waEsc(sw.name) + '" data-v="' + _waEsc(sw.name) + '" style="' + _waSwatchBg(sw.name) + '"></button>';
          }).join('');
          const pop = _waPopShell(el,
            '<div class="rb-wapop-hd"><span>Pick a colour</span><button type="button" class="rb-wapop-x" onclick="window.__waPopClose()">✕</button></div>' +
            '<div class="rb-wapop-swgrid">' + grid + '</div>');
          pop.querySelector('.rb-wapop-swgrid').addEventListener('click', function(e) {
            const b = e.target.closest('.rb-wapop-sw');
            if (!b) return;
            window.__waSawColor = b.dataset.v;
            _waPopClose();
            if (window.__waFormRepaint) window.__waFormRepaint();
          });
        };

        function _setDot(n) {
          const dotsWrap = document.querySelector('#wa-modal .fm-dots');
          if (!dotsWrap) return;
          let dots = dotsWrap.querySelectorAll('.fmd');
          while (dots.length < 3) { const d = document.createElement('span'); d.className = 'fmd'; dotsWrap.appendChild(d); dots = dotsWrap.querySelectorAll('.fmd'); }
          dots.forEach((d, i) => d.classList.toggle('cur', i === n - 1));
        }

        // Downscale + transcode via the shared helper (see _rbDownscale) —
        // kept as a local alias because everything in this closure uses it.
        function _waFileToDataUrl(file) { return _rbDownscale(file); }

        // Bridge for WA.submit (which lives outside this closure): pull the
        // next batch photo straight into step 2, or bail out on a bad file.
        _waBatchAdvance = function(file) {
          _waFileToDataUrl(file).then(_runStep2).catch(function() {
            _waBatchQueue = []; _waBatchTotal = 0; _waBatchDone = 0;
            _origWAClose();
          });
        };

        function _waBatchTag() {
          return _waBatchTotal > 1
            ? `<div style="font-size:10px;letter-spacing:0.14em;color:#9A8070;margin:0 0 6px;">PIECE ${_waBatchDone + 1} OF ${_waBatchTotal}</div>`
            : '';
        }

        function _showStep1() {
          _waFormCss();
          _waForm = null;
          const step = document.querySelector('#wa-modal .fm-step');
          if (!step) return;
          // Annie's 3.3 design (2026-08-20 mock): the batch promise IS the
          // zone — "Add your pieces. One or twenty." with the stacked-photos
          // glyph. Desktop leads with Choose photos + a quiet take-a-photo
          // link; ≤767px stacks Attach photos over an outlined Take a photo
          // (the capture input — never `capture` on the picker, see gotchas).
          step.innerHTML = `
            <h2 class="fm-h">Add your pieces.</h2>
            <p style="font-size:14px;color:var(--ink-faint);margin:0 0 20px;">One or twenty. Robes reads the colour, the cut and the label — and fills in the rest.</p>
            <div id="wa-rb-zone" class="rb-wf-drop">
              <span class="rb-wf-glyph" aria-hidden="true"><svg width="46" height="46" viewBox="0 0 48 48" fill="none"><rect x="8" y="12" width="22" height="28" rx="2" stroke="#C9BCA6" stroke-width="1.4" transform="rotate(-6 8 12)"/><rect x="14" y="10" width="22" height="28" rx="2" stroke="#B8AA92" stroke-width="1.4" transform="rotate(-2 14 10)"/><rect x="21" y="9" width="22" height="28" rx="2" fill="#FAF8F5" stroke="#2A2520" stroke-width="1.5"/></svg></span>
              <span class="rb-wf-drop-h rb-wf-dt">Drop in as many as you like</span>
              <span class="rb-wf-drop-h rb-wf-mb">Add as many as you like</span>
              <span class="rb-wf-drop-s">Robes files them one after another.</span>
              <span class="rb-wf-drop-btns rb-wf-dt">
                <button type="button" class="rb-wf-btn ink" data-pick="lib">Choose photos</button>
              </span>
              <span class="rb-wf-orcam rb-wf-dt">or <button type="button" class="rb-wf-camlink" data-pick="cam">take a photo</button></span>
              <span class="rb-wf-drop-btns rb-wf-mb">
                <button type="button" class="rb-wf-btn ink" data-pick="lib-m">Attach photos</button>
                <button type="button" class="rb-wf-btn line" data-pick="cam">Take a photo</button>
              </span>
              <input id="wa-rb-file" type="file" multiple
                accept="image/*,.jpg,.jpeg,.png,.heic,.heif,.webp"
                style="position:absolute;width:1px;height:1px;opacity:0;overflow:hidden;clip:rect(0 0 0 0);">
              <input id="wa-rb-lib" type="file" multiple accept="image/*"
                style="position:absolute;width:1px;height:1px;opacity:0;overflow:hidden;clip:rect(0 0 0 0);">
              <input id="wa-rb-cam" type="file" accept="image/*" capture="environment"
                style="position:absolute;width:1px;height:1px;opacity:0;overflow:hidden;clip:rect(0 0 0 0);">
            </div>
            <button type="button" class="rb-wf-nophoto" onclick="window.__waManualStart&&__waManualStart()">Add without a photo</button>`;
          _setDot(1);

          // Bundle's validate() calls #wa-label-in.focus() via closure — keep a hidden one so it never throws
          const _dummyLbl = document.createElement('input');
          _dummyLbl.id = 'wa-label-in'; _dummyLbl.type = 'text'; _dummyLbl.style.display = 'none';
          step.appendChild(_dummyLbl);

          const fileInput = document.getElementById('wa-rb-file');
          const zone = document.getElementById('wa-rb-zone');
          function _process(files) {
            const list = Array.prototype.slice.call(files || [])
              .filter(function(f) { return f && (/^image\//.test(f.type) || /\.(heic|heif)$/i.test(f.name)); });
            if (!list.length) return;
            if (_waBatchQueue.length) {
              // Retake mid-batch: the new photo replaces the current piece
              // and any extra picks join the front of the queue.
              _waBatchQueue = list.slice(1).concat(_waBatchQueue);
              _waBatchTotal += list.length - 1;
            } else {
              _waBatchQueue = list.slice(1);
              _waBatchTotal = list.length;
              _waBatchDone = 0;
            }
            _waFileToDataUrl(list[0]).then(_runStep2).catch(function(err) {
              console.warn('[robes-autotag] could not read dropped file:', err);
            });
          }
          if (fileInput) {
            fileInput.addEventListener('change', function() { _process(this.files); });
          }
          // Three inputs, one per source. Take-a-photo goes STRAIGHT to the
          // camera via its capture input; Choose-from-library rides a pure
          // accept="image/*" multiple input — a photos-only accept is what
          // lets iOS open the photo picker DIRECTLY (the extension-carrying
          // #wa-rb-file invites the Files/Drive providers, so iOS shows its
          // source chooser; that input survives for desktop Choose-files +
          // drop + every poke-the-input flow, where the extensions fix the
          // macOS-Safari multi-select quirk).
          const camInput = document.getElementById('wa-rb-cam');
          const libInput = document.getElementById('wa-rb-lib');
          if (camInput) {
            camInput.addEventListener('change', function() { _process(this.files); });
          }
          if (libInput) {
            libInput.addEventListener('change', function() { _process(this.files); });
          }
          if (zone) {
            zone.addEventListener('click', function(e) {
              // Programmatic input.click() bubbles back here — never re-route it
              if (e.target && e.target.tagName === 'INPUT') return;
              const b = e.target.closest && e.target.closest('[data-pick]');
              if (b && b.dataset.pick === 'cam') { if (camInput) camInput.click(); return; }
              if (b && b.dataset.pick === 'lib-m') { (libInput || fileInput).click(); return; }
              if (fileInput) fileInput.click();
            });
          }
          if (zone) {
            ['dragenter', 'dragover'].forEach(function(ev) {
              zone.addEventListener(ev, function(e) {
                e.preventDefault(); e.stopPropagation();
                zone.style.borderColor = '#2A2520'; zone.style.background = '#F3EEE6';
              });
            });
            ['dragleave', 'dragend'].forEach(function(ev) {
              zone.addEventListener(ev, function(e) {
                e.preventDefault(); e.stopPropagation();
                zone.style.borderColor = '#C8B8A2'; zone.style.background = '#FAF8F5';
              });
            });
            zone.addEventListener('drop', function(e) {
              e.preventDefault(); e.stopPropagation();
              zone.style.borderColor = '#C8B8A2'; zone.style.background = '#FAF8F5';
              _process(e.dataTransfer && e.dataTransfer.files);
            });
          }
        }

        function _runStep2(dataUrl) {
          _photoDataUrl = dataUrl;
          const match = dataUrl.match(/^data:([^;]+);base64,(.+)$/);
          if (!match) return;

          const step = document.querySelector('#wa-modal .fm-step');
          if (!step) return;

          const bracketW = 18, bracketT = 2, bracketC = 'rgba(255,255,255,0.9)';
          const bStyle = `position:absolute;width:${bracketW}px;height:${bracketW}px;`;
          step.innerHTML = `
            ${_waBatchTag()}
            <h2 class="fm-h" style="margin-bottom:4px;">Reading your piece…</h2>
            <p style="font-size:14px;color:var(--ink-faint);margin:0 0 16px;">One moment — Robes is looking at the photo.</p>
            <div style="position:relative;height:280px;border-radius:var(--rad);overflow:hidden;background:#1A1410;">
              <img src="${dataUrl}" style="width:100%;height:100%;object-fit:contain;display:block;opacity:0.85;">
              <div style="position:absolute;inset:0;background:rgba(10,8,6,0.18);pointer-events:none;"></div>
              <div style="position:absolute;left:0;right:0;height:2px;animation:rb-scan-line 2.2s linear infinite;pointer-events:none;">
                <div style="height:2px;background:linear-gradient(to right,transparent,rgba(255,255,255,0.9),transparent);box-shadow:0 0 12px 3px rgba(255,255,255,0.35);animation:rb-scan-glow 2.2s ease-in-out infinite;"></div>
                <div style="height:32px;margin-top:-2px;background:linear-gradient(to bottom,rgba(255,255,255,0.06),transparent);pointer-events:none;"></div>
              </div>
              <div style="${bStyle}top:14px;left:14px;border-top:${bracketT}px solid ${bracketC};border-left:${bracketT}px solid ${bracketC};border-radius:2px 0 0 0;"></div>
              <div style="${bStyle}top:14px;right:14px;border-top:${bracketT}px solid ${bracketC};border-right:${bracketT}px solid ${bracketC};border-radius:0 2px 0 0;"></div>
              <div style="${bStyle}bottom:14px;left:14px;border-bottom:${bracketT}px solid ${bracketC};border-left:${bracketT}px solid ${bracketC};border-radius:0 0 0 2px;"></div>
              <div style="${bStyle}bottom:14px;right:14px;border-bottom:${bracketT}px solid ${bracketC};border-right:${bracketT}px solid ${bracketC};border-radius:0 0 2px 0;"></div>
              <div style="position:absolute;bottom:0;left:0;right:0;padding:14px 16px;background:linear-gradient(to top,rgba(10,8,6,0.75) 60%,transparent);">
                <span id="wa-read-txt" style="color:rgba(255,255,255,0.9);font-size:13px;letter-spacing:0.04em;">Identifying colour and fabric…</span>
              </div>
            </div>`;
          _setDot(2);

          // Keep hidden #wa-label-in so bundle's validate closure never throws
          const _dummyLbl2 = document.createElement('input');
          _dummyLbl2.id = 'wa-label-in'; _dummyLbl2.type = 'text'; _dummyLbl2.style.display = 'none';
          step.appendChild(_dummyLbl2);

          const readTexts = ['Identifying colour and fabric…','Reading the silhouette…','Checking for brand details…'];
          let ti = 0;
          const txtInterval = setInterval(() => {
            ti = (ti + 1) % readTexts.length;
            const el = document.getElementById('wa-read-txt');
            if (el) el.textContent = readTexts[ti];
          }, 1800);

          fetch('/api/wardrobe/analyse', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ data: match[2], mimeType: match[1], userId: _waUid() || undefined })
          })
          .then(r => {
            if (!r.ok) throw new Error('analyse ' + r.status);
            return r.json();
          })
          .then(tag => {
            clearInterval(txtInterval);
            _runStep3(dataUrl, tag);
          })
          .catch(err => {
            clearInterval(txtInterval);
            console.warn('[robes-autotag] analyse network error, showing empty step 3:', err);
            _runStep3(dataUrl, { label: '', category: 'Other', color: '', brand: '', notes: '', item_dna: { display: {}, structural_dna: { silhouette_fit: [] }, ai_generated_notes: '' } });
          });
        }

        // ══ The one confirm screen (add/edit redesign 2026-08-05) ═════════
        // Fast add: the analyse lands on a READ-ONLY summary — the photo
        // with tag pops, a four-row ledger — over one "Add to wardrobe" CTA.
        // Everything editable lives behind "Edit the details" (progressive
        // disclosure), and the two tag axes (Season / Wear it for) + notes
        // behind "Add tags and notes". ONE renderer serves the photo add,
        // add-without-a-photo, batch pieces and the edit modal; field state
        // bridges to WA.submit through the window.__waSaw* globals exactly
        // as before. Silhouette & fit is CUT from the flow (locked product
        // decision: wrong hand-entered tags → worse output) — the analyse
        // still lands in item_dna untouched, it just isn't a form field.
        var _waForm = null; // {mode:'add'|'manual'|'edit', view:'summary'|'details'|'tags', photo, readable, revealed}

        function _sawEsc(s) {
          return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/"/g, '&quot;');
        }

        function _waFormCss() {
          if (document.getElementById('rb-wa-form-style')) return;
          const st = document.createElement('style');
          st.id = 'rb-wa-form-style';
          st.textContent = [
            // step 1 — the image
            '.rb-wf-drop{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;border:1.5px dashed #D8CFC0;border-radius:var(--rad);background:#FAF8F5;cursor:pointer;text-align:center;padding:34px 22px 30px;box-sizing:border-box;position:relative}',
            '.rb-wf-glyph{display:block;line-height:0;margin-bottom:2px}',
            '.rb-wf-drop-h{font-family:var(--font-serif,Georgia,serif);font-weight:300;font-size:26px;color:#2A2520}',
            '.rb-wf-drop-s{font-size:13px;color:var(--ink-faint);margin-top:-8px}',
            '.rb-wf-orcam{font-size:13px;color:var(--ink-faint);margin-top:-2px}',
            '.rb-wf-camlink{background:none;border:none;padding:0 0 1px;font-family:inherit;font-size:13px;color:var(--ink,#202021);border-bottom:1px solid rgba(32,32,33,0.35);cursor:pointer}',
            '.rb-wf-drop-btns{display:flex;gap:10px;flex-wrap:wrap;justify-content:center}',
            '.rb-wf-btn{display:inline-flex;align-items:center;justify-content:center;padding:13px 24px;border-radius:100px;font-size:11px;font-weight:500;letter-spacing:.14em;text-transform:uppercase;white-space:nowrap;cursor:pointer;box-sizing:border-box}',
            '.rb-wf-btn.ink{background:var(--ink,#202021);color:#FAF8F5}',
            '.rb-wf-btn.line{border:1px solid var(--ink,#202021);color:var(--ink,#202021)}',
            // Desktop shows the drop-first variant (no camera on a desktop);
            // ≤767px swaps in the snap/attach pair (screens 02 revised / 10)
            '.rb-wf-mb{display:none}',
            '.rb-wf-linkrow{display:flex;align-items:center;gap:14px;margin:18px 0 0}',
            '.rb-wf-linkrow input{flex:1;min-width:0;border:1px solid #E7E0CF;background:#fff;padding:12px 14px;font-size:14px;font-family:inherit;color:#2A2520;border-radius:var(--rad-sm);cursor:pointer}',
            '.rb-wf-nophoto{display:block;width:100%;margin-top:18px;padding:16px 0 2px;border:none;border-top:1px solid #EFE9DC;background:none;text-align:center;font-size:13px;color:var(--ink-faint);cursor:pointer;font-family:inherit}',
            '.rb-wf-nophoto:hover{color:var(--ink)}',
            '@media(max-width:767px){.rb-wf-dt{display:none}.rb-wf-mb{display:block}.rb-wf-drop-btns.rb-wf-mb{display:flex;flex-direction:column;align-self:stretch}.rb-wf-drop-btns .rb-wf-btn{width:100%}}',
            // the reveal — photo panel, tag pops, banner (contain, never
            // cover: a portrait garment photo must not crop top/bottom)
            '.rb-saw-panel{position:relative;height:300px;border-radius:var(--rad);overflow:hidden;background:#1A1410;margin-bottom:14px}',
            '.rb-saw-panel>img{width:100%;height:100%;object-fit:contain;display:block}',
            '.rb-saw-retake{position:absolute;top:10px;right:10px;z-index:5;background:rgba(250,248,245,0.92);border:1px solid #D8CEBC;border-radius:100px;padding:6px 13px;font-size:12px;color:#6A5E54;cursor:pointer;font-family:inherit}',
            '.rb-saw-tag{position:absolute;display:inline-flex;align-items:center;gap:7px;background:rgba(250,248,245,0.94);border:1px solid #E3DCD0;border-radius:100px;padding:6px 10px;font-weight:500;font-size:10px;letter-spacing:0.14em;text-transform:uppercase;color:#2A2520;white-space:nowrap;max-width:84%;overflow:hidden;text-overflow:ellipsis;box-shadow:0 2px 10px rgba(32,32,33,0.18);opacity:0;animation:rbSawPop .5s cubic-bezier(0.22,1,0.36,1) both;z-index:3}',
            ".rb-saw-tag::before{content:'';width:5px;height:5px;border-radius:50%;background:#AE9290;flex:none}",
            '.rb-saw-banner{position:absolute;left:10px;right:10px;bottom:10px;z-index:3;background:rgba(32,32,33,0.86);color:#FAF8F5;border-radius:2px;padding:11px 14px;font-family:var(--font-serif,Georgia,serif);font-weight:300;font-size:16px;letter-spacing:0.01em;text-align:center;opacity:0;animation:rbSawPop .55s cubic-bezier(0.22,1,0.36,1) both}',
            '@keyframes rbSawPop{from{opacity:0;transform:translateY(6px) scale(0.7)}60%{opacity:1;transform:translateY(0) scale(1.04)}to{opacity:1;transform:none}}',
            // the ledger — four read-only rows; tapping one opens the
            // details editor on that field
            '.rb-saw-read{list-style:none;margin:0 0 14px;padding:0}',
            '.rb-saw-row{display:flex;align-items:baseline;gap:14px;padding:12px 2px;border-bottom:1px solid #EFE9DC;cursor:pointer}',
            '.rb-saw-num{font-family:var(--font-serif,Georgia,serif);font-weight:300;font-size:15px;color:#C9BCA6;width:18px;flex:none}',
            '.rb-saw-lbl{flex:1;font-weight:500;font-size:10px;letter-spacing:0.2em;text-transform:uppercase;color:#9A8070;align-self:center}',
            '.rb-saw-val{font-family:var(--font-serif,Georgia,serif);font-weight:300;font-size:17px;color:#2A2520;text-align:right;max-width:60%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}',
            '.rb-saw-val.is-on{color:#B9AC96;font-style:italic;animation:rbSawPulse 1.4s ease-in-out infinite}',
            '.rb-saw-dot{display:inline-block;width:16px;height:16px;border-radius:50%;vertical-align:-2px;margin-right:8px}',
            '@keyframes rbSawPulse{0%,100%{opacity:1}50%{opacity:.45}}',
            // section toggle rows (Edit the details / Add tags and notes)
            '.rb-saw-toggle{display:flex;align-items:center;justify-content:space-between;gap:10px;width:100%;background:#FAF8F5;border:1px solid #E3DCD0;border-radius:var(--rad-sm);padding:13px 15px;font-size:13.5px;color:#2A2520;cursor:pointer;font-family:inherit;margin-bottom:14px;box-sizing:border-box;text-align:left}',
            '.rb-saw-toggle .hint{font-family:var(--font-serif,Georgia,serif);font-style:italic;font-size:14px;color:var(--ink-faint);font-weight:300;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}',
            '.rb-saw-toggle .car{font-size:12px;color:var(--ink-faint);flex:none}',
            // compact header (details / tags open — nothing shown twice)
            '.rb-wf-head{display:flex;gap:16px;align-items:center;border-bottom:1px solid #E7E0CF;padding-bottom:16px;margin-bottom:14px}',
            '.rb-wf-thumb{width:64px;height:64px;flex:none;background:#232120;border-radius:var(--rad-sm);overflow:hidden}',
            '.rb-wf-thumb img{width:100%;height:100%;object-fit:cover;display:block}',
            '.rb-wf-thumb.empty{background:#EFE9DC;border:1px dashed #D8CFC0;box-sizing:border-box}',
            '.rb-wf-headtxt{flex:1;min-width:0}',
            '.rb-wf-title{display:block;font-family:var(--font-serif,Georgia,serif);font-weight:300;font-size:22px;line-height:1.1;color:#2A2520;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}',
            '.rb-wf-meta{display:block;font-size:11.5px;color:var(--ink-faint);margin-top:4px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}',
            '.rb-wf-headact{flex:none;background:none;border:none;padding:0 0 2px;font-size:12px;color:var(--ink-faint);border-bottom:1px solid #E7E0CF;cursor:pointer;font-family:inherit}',
            // fields
            '.rb-wf-lbl{display:block;font-size:9.5px;letter-spacing:.2em;text-transform:uppercase;font-weight:500;color:#9A8070;margin-bottom:6px}',
            '.rb-wf-input{width:100%;box-sizing:border-box;padding:12px 14px;border:1px solid #D8CEBC;border-radius:var(--rad-sm);font-size:14.5px;font-family:inherit;background:#fff;color:#2A2520}',
            '.rb-wf-grid2{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:12px}',
            '@media(max-width:520px){.rb-wf-grid2{grid-template-columns:1fr}}',
            '.rb-wf-field{display:flex;align-items:center;justify-content:space-between;gap:8px;box-sizing:border-box;width:100%;padding:12px 14px;border:1px solid #D8CEBC;border-radius:var(--rad-sm);font-size:14.5px;background:#fff;color:#2A2520;cursor:pointer;font-family:inherit;text-align:left}',
            '.rb-wf-field span:first-child{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}',
            '.rb-wf-field .car{color:var(--ink-faint);font-size:11px;flex:none}',
            '.rb-wf-field.empty span:first-child{color:#C4B8A4}',
            '.rb-wf-field.off{opacity:.45;cursor:default}',
            // colour — a single swatch with a quiet Change affordance
            '.rb-wf-colour{display:flex;align-items:center;gap:12px;padding:4px 2px}',
            '.rb-wf-dot{width:26px;height:26px;border-radius:50%;flex:none}',
            '.rb-wf-dot.empty{background:#F5F2E0;border:1px dashed #D8CFC0;box-sizing:border-box}',
            '.rb-wf-colname{font-size:14.5px;color:#2A2520}',
            '.rb-wf-colname.ph{color:#C4B8A4}',
            '.rb-wf-change{margin-left:auto;background:none;border:none;padding:0 0 2px;font-size:12px;letter-spacing:.04em;color:var(--ink-faint);border-bottom:1px solid #E7E0CF;cursor:pointer;font-family:inherit}',
            // tag axes — two visibly different selected tints (Season sage,
            // Wear-it-for rose) so the axes never read as one control
            '.rb-wf-chips{display:flex;flex-wrap:wrap;gap:8px}',
            '.rb-wf-chip{padding:8px 15px;border-radius:100px;border:1px solid #E7E0CF;background:#fff;font-size:13px;color:#2A2520;cursor:pointer;font-family:inherit;transition:all .15s}',
            '.rb-wf-chip.sea.on{background:#E3E1CC;border-color:#E3E1CC}',
            '.rb-wf-chip.ctx.on{background:#D4C8C4;border-color:#D4C8C4}',
            '.rb-wf-chip.add{border-style:dashed;color:var(--ink-faint)}',
            '.rb-wf-taghd{margin-top:16px;padding-top:16px;border-top:1px solid #EFE9DC}',
            '.rb-wf-taghd.first{margin-top:0;padding-top:0;border-top:none}',
            // photo slot / attached photo (manual + unreadable paths)
            '.rb-wf-slot{height:130px;border:1.5px dashed #D8CFC0;border-radius:var(--rad);background:#FAF8F5;display:flex;align-items:center;justify-content:center;margin-bottom:16px}',
            '.rb-wf-slot .rb-wf-btn{padding:11px 20px}',
            '.rb-wf-photo{position:relative;height:200px;border-radius:var(--rad);overflow:hidden;background:#1A1410;margin-bottom:16px}',
            '.rb-wf-photo img{width:100%;height:100%;object-fit:contain;display:block}',
            // CTA + edit-only delete
            '.rb-wf-cta{width:100%;padding:16px;background:var(--ink,#202021);color:#FAF8F5;border:none;border-radius:100px;font-size:11.5px;font-weight:500;letter-spacing:.16em;text-transform:uppercase;cursor:pointer;font-family:inherit;margin-top:14px}',
            '.rb-wf-del{display:block;width:100%;margin-top:8px;padding:12px;background:none;border:none;cursor:pointer;font-size:11px;color:var(--ink-faint);letter-spacing:.06em;font-family:inherit}',
            '.rb-wf-del:hover{color:#b03030}',
            // picker popover / mobile sheet (taxonomy fields + colour)
            '.rb-wapop{position:fixed;z-index:990;background:#FDFCFA;border:1px solid #E7E0CF;border-radius:var(--rad-sm);box-shadow:0 18px 44px -10px rgba(32,32,33,.28);display:flex;flex-direction:column;overflow:hidden}',
            '.rb-wapop.sheet{left:0;right:0;bottom:0;top:auto;width:auto;max-height:72vh;border-radius:18px 18px 0 0}',
            '.rb-wapop-hd{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:13px 16px 9px;font-size:9.5px;letter-spacing:.2em;text-transform:uppercase;font-weight:500;color:#9A8070;flex:none}',
            '.rb-wapop.sheet .rb-wapop-hd{font-family:var(--font-serif,Georgia,serif);font-size:21px;letter-spacing:0;text-transform:none;font-weight:300;color:#2A2520;padding:18px 20px 10px}',
            '.rb-wapop-x{background:none;border:none;font-size:14px;color:var(--ink-faint);cursor:pointer;padding:2px 4px;font-family:inherit}',
            '.rb-wapop-list{overflow-y:auto;padding:0 6px 8px}',
            '.rb-wapop.sheet .rb-wapop-list{padding:0 14px 22px}',
            '.rb-wapop-row{display:flex;align-items:center;justify-content:space-between;gap:10px;width:100%;text-align:left;background:none;border:none;border-bottom:1px solid #EFE9DC;padding:12px 10px;font-size:14px;color:#2A2520;cursor:pointer;font-family:inherit}',
            '.rb-wapop-row:last-child{border-bottom:none}',
            '.rb-wapop-row:hover{background:#F6F2EA}',
            '.rb-wapop-row.sel{font-weight:500}',
            '.rb-wapop-row.muted span:first-child{color:var(--ink-faint);font-style:italic}',
            '.rb-wapop-chk{flex:none}',
            '.rb-wapop-swgrid{display:grid;grid-template-columns:repeat(7,30px);gap:12px;padding:6px 16px 16px}',
            '.rb-wapop.sheet .rb-wapop-swgrid{grid-template-columns:repeat(auto-fill,minmax(34px,1fr));padding:10px 20px 26px}',
            '.rb-wapop-sw{width:30px;height:30px;border-radius:50%;border:none;cursor:pointer;padding:0;box-shadow:inset 0 1px 3px rgba(0,0,0,.12),0 0 0 1px rgba(0,0,0,.06)}',
            '.rb-wapop.sheet .rb-wapop-sw{width:34px;height:34px}',
            '.rb-wapop-sw.sel{outline:2px solid var(--ink,#202021);outline-offset:2.5px}',
            '@media(prefers-reduced-motion:reduce){.rb-saw-tag,.rb-saw-banner{animation-duration:0s}.rb-saw-val.is-on{animation:none}}',
          ].join('\n');
          document.head.appendChild(st);
        }

        // Map Gemini's returned colour names → our palette names
        const GEMINI_MAP = {
          'White':'White','Cream':'Cream','Alabaster':'Cream',
          'Navy':'Navy','Denim blue':'Navy','Royal blue':'Cobalt','Blue':'Cobalt',
          'Light grey':'Charcoal','Charcoal':'Charcoal',
          'Black':'Black','Chocolate':'Espresso',
          'Tan':'Camel','Sand':'Camel','Camel':'Camel',
          'Taupe':'Taupe','Mauve':'Taupe',
          'Khaki':'Olive','Sage':'Olive','Olive':'Olive',
          'Aubergine':'Aubergine',
          'Dark green':'Forest','Forest':'Forest',
          'Burgundy':'Bordeaux','Bordeaux':'Bordeaux',
          'Blush':'Blush','Dusty rose':'Blush',
          'Yellow':'Ochre','Ochre':'Ochre',
          'Hot pink':'Magenta','Magenta':'Magenta',
          'Cobalt':'Cobalt','Emerald':'Emerald','Green':'Emerald',
          'Rust':'Vermillion','Orange':'Vermillion','Vermillion':'Vermillion',
          'Acid':'Acid',
          'Multi':'Print','Stripe':'Print','Print':'Print',
        };

        const LEDGER_LBLS = ['The piece', 'Brand', 'Category', 'Colour'];
        // The DISPLAYED category is always the taxonomy sheet's L1 (or the
        // legacy mapping for degrade/legacy state) — the stored `category`
        // stays the legacy enum via the fold at save time.
        function _waFormSheet() {
          const s = window.__waSawTaxSel;
          if (s && s.sheet) return s.sheet;
          return _WA_LEGACY_TO_SHEET[window.__waSawCat] || window.__waSawCat || '';
        }
        function _waFormMeta() {
          const s = window.__waSawTaxSel;
          return [window.__waSawBrand, _waFormSheet(), s && s.l3, window.__waSawColor]
            .filter(Boolean).join(' · ');
        }
        function _waLedgerVals() {
          const colour = window.__waSawColor || '';
          return [
            _sawEsc(window.__waSawLabel || ''),
            _sawEsc(window.__waSawBrand || 'Unlabelled'),
            _sawEsc(_waFormSheet() || '—'),
            colour ? '<span class="rb-saw-dot" style="' + _waSwatchBg(colour) + '"></span>' + _sawEsc(colour) : '—',
          ];
        }

        function _waFormPaint(focusSel) {
          _waFormCss();
          const step = document.querySelector('#wa-modal .fm-step');
          const f = _waForm;
          if (!step || !f) return;
          _waPopClose();
          const d = window.__rbWaDetail || { seasons: [], wear: [], addingTag: false };
          const treeOn = !!_waTaxTree;
          const s = window.__waSawTaxSel;
          const label = window.__waSawLabel || '';
          const colour = window.__waSawColor || '';
          const isEdit = f.mode === 'edit';
          const batch = f.mode === 'add' ? _waBatchTag() : '';

          function tog(view, text, car, hint) {
            return '<button type="button" class="rb-saw-toggle" onclick="window.__waFormView(\'' + view + '\')">' +
              '<span>' + text + '</span>' +
              (hint ? '<span class="hint">' + hint + '</span>' : '') +
              '<span class="car">' + car + '</span></button>';
          }
          const nTags = (d.band && d.band !== 'year_round' ? 1 : 0) +
            d.wear.filter(function(w) { return w !== 'everyday'; }).length;
          const tagsToggle = tog('tags',
            '<span style="color:var(--ink-faint);margin-right:8px">+</span>Add tags and notes', '',
            nTags ? nTags + ' set' : 'season, wear it for, notes');
          // Bridge, not a duplicate (IA 2026-08-08): the piece links into
          // the Lookbook where its looks live — the cross-link that
          // replaced the wardrobe's Looks tab.
          const styledIn = isEdit && typeof _lkLooks !== 'undefined' && Array.isArray(_lkLooks)
            ? _lkLooks.filter(function(l) { return _lkPieceIds(l).map(String).indexOf(String(_waEditId)) > -1; }).length
            : 0;
          const cta = '<button id="wa-saw-cta" class="rb-wf-cta" onclick="window.__waSawSubmit&&window.__waSawSubmit()">' +
              (isEdit ? 'Update piece →' : 'Add to wardrobe →') + '</button>' +
            (styledIn ? '<button type="button" class="rb-wf-del" style="color:var(--ink-soft)" onclick="window.__waFormLooks()">Styled in ' + styledIn + ' look' + (styledIn === 1 ? '' : 's') + ' →</button>' : '') +
            (isEdit ? '<button type="button" class="rb-wf-del" onclick="window.__waFormDelete()">Remove from wardrobe</button>' : '');
          const photoIn = f.mode !== 'add'
            ? '<input id="rb-wf-photoin" type="file" accept="image/*,.jpg,.jpeg,.png,.heic,.heif,.webp" style="position:absolute;width:1px;height:1px;opacity:0;overflow:hidden;clip:rect(0 0 0 0);">'
            : '';

          const compactHead = function(action) {
            return '<div class="rb-wf-head">' +
              '<span class="rb-wf-thumb' + (f.photo ? '' : ' empty') + '">' + (f.photo ? '<img id="rb-wf-thumbimg" alt="">' : '') + '</span>' +
              '<span class="rb-wf-headtxt">' +
                '<span class="rb-wf-title">' + _sawEsc(label || 'New piece') + '</span>' +
                '<span class="rb-wf-meta">' + _sawEsc(_waFormMeta()) + '</span>' +
              '</span>' + action + '</div>';
          };
          const photoAct = '<button type="button" class="rb-wf-headact" onclick="window.__waFormPhoto()">' +
            (f.photo ? (f.mode === 'add' ? 'Retake' : 'Change photo') : 'Add a photo') + '</button>';
          const editAct = '<button type="button" class="rb-wf-headact" onclick="window.__waFormView(\'details\')">Edit</button>';

          let html = '';
          if (f.view === 'summary') {
            // Screen 03 — what Robes saw, read-only. Rows open the editor.
            const chips = [];
            const sheet = _waFormSheet();
            if (sheet) chips.push(sheet);
            if (s && s.l2) chips.push(s.l2);
            if (window.__waSawBrand) chips.push(window.__waSawBrand);
            if (colour) chips.push(colour);
            if (s && s.l3) chips.push(s.l3);
            const SAW_SPOTS = [
              { top: '9%', left: '7%' },
              { top: '25%', right: '7%' },
              { top: '43%', left: '9%' },
              { top: '58%', right: '10%' },
              { top: '74%', left: '7%' },
            ];
            const tagsHtml = chips.slice(0, SAW_SPOTS.length).map(function(c, idx) {
                const sp = SAW_SPOTS[idx];
                const pos = 'top:' + sp.top + ';' + (sp.left ? 'left:' + sp.left : 'right:' + sp.right) + ';';
                const anim = f.revealed ? 'animation:none;opacity:1;' : 'animation-delay:' + (0.15 + idx * 0.4).toFixed(2) + 's;';
                return '<span class="rb-saw-tag" style="' + pos + anim + '">' + _sawEsc(c) + '</span>';
              }).join('') +
              '<span class="rb-saw-banner" style="' + (f.revealed ? 'animation:none;opacity:1;' : 'animation-delay:' + (0.35 + Math.min(chips.length, SAW_SPOTS.length) * 0.4).toFixed(2) + 's;') + '">' + _sawEsc(label) + '</span>';
            const vals = _waLedgerVals();
            const ledger = '<ul class="rb-saw-read" id="rb-saw-read">' + LEDGER_LBLS.map(function(l, idx) {
              return '<li class="rb-saw-row" onclick="window.__waFormView(\'details\',' + idx + ')">' +
                '<span class="rb-saw-num">' + String(idx + 1).padStart(2, '0') + '</span>' +
                '<span class="rb-saw-lbl">' + l + '</span>' +
                '<span class="rb-saw-val' + (f.revealed ? '' : ' is-on') + '">' + (f.revealed ? vals[idx] : 'Reading') + '</span></li>';
            }).join('') + '</ul>';
            html = batch +
              '<h2 class="fm-h" style="margin-bottom:4px;">Here’s what Robes <em style="font-style:italic;color:#9A7060">saw.</em></h2>' +
              '<p style="font-size:13px;color:var(--ink-faint);margin:0 0 16px;">Filed from your photo — adjust the details only if something isn’t quite right.</p>' +
              '<div class="rb-saw-panel" id="rb-saw-panel"><img id="wa-saw-photo" alt="">' + tagsHtml +
              '<button type="button" class="rb-saw-retake" onclick="window.__waRetake&&window.__waRetake()">↺ Retake</button></div>' +
              ledger +
              tog('details', 'Edit the details', '▾') +
              cta;
          } else if (f.view === 'details') {
            // Screens 04/05/11 — the editable fields, core set only.
            let head;
            if (isEdit || (f.mode === 'add' && f.readable)) {
              head = compactHead(photoAct) + (f.mode === 'add' && f.readable ? tog('summary', 'Hide the details', '▴') : '');
            } else {
              // Manual add / unreadable photo — full headline, empty slot.
              const sub = f.mode === 'add' && !f.readable
                ? '<p style="font-size:13px;color:var(--ink-faint);margin:0 0 14px;">Robes couldn’t quite read this one — give it a name and it files all the same.</p>'
                : '';
              head = '<h2 class="fm-h" style="margin-bottom:' + (sub ? '4px' : '14px') + ';">Add a piece.</h2>' + sub +
                (f.photo
                  ? '<div class="rb-wf-photo"><img id="rb-wf-photoimg" alt=""><button type="button" class="rb-saw-retake" onclick="window.__waFormPhoto()">↺ Retake</button></div>'
                  : '<div class="rb-wf-slot"><span class="rb-wf-btn line" onclick="window.__waFormPhoto()">Add a photo</span></div>');
            }
            const catVal = treeOn ? (s && s.sheet) || '' : window.__waSawCat || '';
            const hasL2s = treeOn && s && s.sheet && _waTaxL2s(s.sheet).length > 0;
            const fields =
              '<div>' +
                '<label class="rb-wf-lbl">The piece</label>' +
                '<input id="wa-saw-label" class="rb-wf-input" placeholder="Name the piece" value="' + _sawEsc(label) + '" oninput="window.__waSawLabel=this.value">' +
              '</div>' +
              '<div class="rb-wf-grid2">' +
                '<div><label class="rb-wf-lbl">Brand</label>' +
                  '<input id="wa-saw-brand" class="rb-wf-input" placeholder="Start typing…" value="' + _sawEsc(window.__waSawBrand || '') + '" oninput="window.__waSawBrand=this.value"></div>' +
                '<div><label class="rb-wf-lbl">Category</label>' +
                  '<button type="button" id="wa-saw-cat" class="rb-wf-field' + (catVal ? '' : ' empty') + '" onclick="window.__waFieldPick(\'cat\',this)"><span>' + _sawEsc(catVal || 'Choose') + '</span><span class="car">▾</span></button></div>' +
              '</div>' +
              (hasL2s
                ? '<div class="rb-wf-grid2">' +
                  '<div><label class="rb-wf-lbl">Subcategory</label>' +
                    '<button type="button" id="wa-saw-l2" class="rb-wf-field' + (s.l2 ? '' : ' empty') + '" onclick="window.__waFieldPick(\'l2\',this)"><span>' + _sawEsc(s.l2 || 'Choose') + '</span><span class="car">▾</span></button></div>' +
                  '<div><label class="rb-wf-lbl">Item type</label>' +
                    '<button type="button" id="wa-saw-l3" class="rb-wf-field' + (s.l3 ? '' : ' empty') + (s.l2 ? '' : ' off') + '" ' + (s.l2 ? '' : 'disabled ') + 'onclick="window.__waFieldPick(\'l3\',this)"><span>' + _sawEsc(s.l3 || 'Choose') + '</span><span class="car">▾</span></button></div>' +
                '</div>'
                : '') +
              '<div style="margin-top:12px;margin-bottom:14px">' +
                '<label class="rb-wf-lbl">Colour</label>' +
                '<div class="rb-wf-colour">' +
                  '<span class="rb-wf-dot' + (colour ? '' : ' empty') + '" style="' + (colour ? _waSwatchBg(colour) : '') + '"></span>' +
                  '<span class="rb-wf-colname' + (colour ? '' : ' ph') + '">' + _sawEsc(colour || 'Pick a colour') + '</span>' +
                  '<button type="button" class="rb-wf-change" onclick="window.__waColourPop(this)">Change</button>' +
                '</div>' +
              '</div>';
            html = batch + head + fields + tagsToggle + cta + photoIn;
          } else {
            // f.view === 'tags' — screen 06: two axes held apart, notes last.
            // The pre-fill preview is computed AT PAINT, not once at init.
            // Two reasons: the taxonomy fetch is a boot-time round trip, so
            // seeding at init raced it and the same piece could show either
            // the real pre-fill or the year_round fallback; and re-deriving
            // means the preview FOLLOWS a category correction, which is what
            // the trigger will actually do at save. Stops the moment she
            // touches either axis — from then on the form is hers. Never on
            // edit: there the stored row is the truth.
            if (_waForm.mode !== 'edit' && !d.bandTouched && !d.wearTouched) {
              const _sel = window.__waSawTaxSel;
              const _seed = _waDetailSeed(window.__waSawCat || '', (_sel && _sel.l2) || '');
              d.band = _seed.band; d.wear = _seed.wear;
            }
            // Season is ONE tap of three now (ADR-002 §1): picking both
            // bands IS year-round, so the multi-select collapses.
            const seaChips = WA_BANDS.map(function(b) {
              const on = d.band === b;
              return '<button type="button" class="rb-wf-chip sea' + (on ? ' on' : '') + '" onclick="window.__waTagTog(\'band\',\'' + b + '\')">' + _sawEsc(WA_BAND_LABELS[b]) + '</button>';
            }).join('');
            // Wear it for draws on the SHARED namespace — the seven seeds
            // plus every tag she has made anywhere, on a piece or a look.
            // Uncapped: a cap forces a choice between a functional tag and a
            // capsule tag, which is the choice that stops capsules forming.
            const ctxAll = _tgWearOptions()
              .concat(d.wear.filter(function(w) { return _tgWearOptions().indexOf(w) === -1; }));
            const ctxChips = ctxAll.map(function(w) {
              const on = d.wear.indexOf(w) !== -1;
              return '<button type="button" class="rb-wf-chip ctx' + (on ? ' on' : '') + '" onclick="window.__waTagTog(\'wear\',\'' + _sawEsc(w).replace(/'/g, "\\'") + '\')">' + _sawEsc(_tgLabel('wear_for', w)) + '</button>';
            }).join('') + (d.addingTag
              ? '<input id="rb-wf-tagin" class="rb-wf-input" placeholder="Type &amp; press Enter" onkeydown="window.__waTagKey(event,this)" onblur="window.__waTagKey(event,this)" style="width:150px;border-radius:100px;padding:8px 15px;font-size:13px">'
              : '<button type="button" class="rb-wf-chip ctx add" onclick="window.__waTagStart()">+ tag</button>');
            html = batch + compactHead(editAct) +
              tog('details', 'Hide tags and notes', '▴') +
              '<div class="rb-wf-taghd first"><label class="rb-wf-lbl" style="margin-bottom:10px">Season</label><div class="rb-wf-chips">' + seaChips + '</div></div>' +
              '<div class="rb-wf-taghd"><label class="rb-wf-lbl" style="margin-bottom:10px">Wear it for</label><div class="rb-wf-chips">' + ctxChips + '</div></div>' +
              '<div class="rb-wf-taghd"><label class="rb-wf-lbl">Notes</label>' +
                '<textarea id="wa-saw-notes" class="rb-wf-input" placeholder="Fit, fabric, how you like to wear it." style="resize:none;height:72px" oninput="window.__waSawNotes=this.value">' + String(window.__waSawNotes || '').replace(/</g, '&lt;') + '</textarea></div>' +
              cta + photoIn;
          }

          step.innerHTML = html;

          // Hidden dummy #wa-label-in — the bundle's open() focuses it on a
          // 220ms timer (and validate() reads it); our form replaces the
          // bundle fields at 150ms, so without this the edit path throws.
          // At submit time it simply shadows the hidden-host copy for the
          // label — __waSawSubmit writes and WA.submit reads the same node.
          if (!document.getElementById('wa-label-in')) {
            const dummy = document.createElement('input');
            dummy.id = 'wa-label-in';
            dummy.type = 'text';
            dummy.style.display = 'none';
            step.appendChild(dummy);
          }

          // Photo srcs set via DOM, never innerHTML — large data URLs truncate.
          const p1 = document.getElementById('wa-saw-photo');
          if (p1 && f.photo) p1.src = f.photo;
          const p2 = document.getElementById('rb-wf-thumbimg');
          if (p2 && f.photo) p2.src = f.photo;
          const p3 = document.getElementById('rb-wf-photoimg');
          if (p3 && f.photo) p3.src = f.photo;

          // Manual/edit photo replace — attach only, no re-analyse (she is
          // filing by hand; the scan runs only through step 1).
          const pin = document.getElementById('rb-wf-photoin');
          if (pin) {
            pin.addEventListener('change', function() {
              const file = this.files && this.files[0];
              if (!file) return;
              _waFileToDataUrl(file).then(function(url) {
                _photoDataUrl = url;
                if (_waForm) { _waForm.photo = url; _waFormPaint(); }
              }).catch(function() { _waShowToast('Could not read that image'); });
            });
          }

          // The filing reveal — ledger rows fill one at a time. Bails
          // silently if the step re-renders (retake, batch advance) mid-play.
          if (f.view === 'summary' && f.readable && !f.revealed) {
            const vals = _waLedgerVals();
            let rc = 0;
            const revealTick = function() {
              const spans = document.querySelectorAll('#rb-saw-read .rb-saw-val');
              if (!spans.length) return;
              spans.forEach(function(sp, idx) {
                const done = idx < rc;
                sp.innerHTML = done ? vals[idx] : 'Reading';
                sp.className = 'rb-saw-val' + (done ? '' : ' is-on');
              });
              if (rc < vals.length) { rc++; setTimeout(revealTick, 420); }
              else f.revealed = true;
            };
            setTimeout(revealTick, 250);
          }

          if (focusSel) {
            const el = document.querySelector(focusSel);
            if (el && el.focus) el.focus();
          }
        }
        window.__waFormRepaint = function() { if (_waForm) _waFormPaint(); };

        window.__waFormView = function(v, focusIdx) {
          if (!_waForm) return;
          _waForm.view = v;
          _waFormPaint(focusIdx === 0 ? '#wa-saw-label' : focusIdx === 1 ? '#wa-saw-brand' : null);
        };

        // Two tag axes, held apart: 'seasons' files into wardrobe_items.
        // band (single-select), 'wear' into the shared tag namespace.
        // Each axis carries a visible DEFAULT chip (Year-round / Everyday):
        // exclusive with the specific tags, re-selected when the last one is
        // removed, and stripped back to null at save — the default state is
        // displayed, never stored.
        window.__waTagTog = function(axis, val) {
          const d = window.__rbWaDetail;
          if (!d) return;
          if (axis === 'band') {
            // Single-select, and never empty: tapping the live band is a
            // no-op rather than clearing it. An unset season is expressed by
            // year_round, not by absence.
            d.band = val;
            d.bandTouched = true;
          } else {
            const i = d.wear.indexOf(val);
            if (i === -1) d.wear.push(val); else d.wear.splice(i, 1);
            d.wearTouched = true;
          }
          _waFormPaint();
        };
        window.__waTagStart = function() {
          const d = window.__rbWaDetail;
          if (!d) return;
          d.addingTag = true;
          _waFormPaint('#rb-wf-tagin');
        };
        window.__waTagKey = function(e, el) {
          const d = window.__rbWaDetail;
          // Enter commits and repaints (removing the input) — the orphaned
          // input then fires blur, which must not repaint again mid-remove.
          if (!d || !d.addingTag) return;
          if (e.type === 'blur' || e.key === 'Enter') {
            if (e.key === 'Enter') e.preventDefault();
            const v = (el.value || '').trim().slice(0, 28);
            const slug = _rbTagSlug(v);
            // Store the slug; remember her label so the chip reads as she
            // typed it before the tags row exists. A typed value matching an
            // existing tag selects it rather than minting a near-duplicate.
            if (slug && d.wear.indexOf(slug) === -1) {
              d.wear.push(slug);
              d.wearTouched = true;
              if (!_tgFind('wear_for', slug)) {
                _tgTags.push({ id: null, kind: 'wear_for', label: v, slug, is_seed: false });
              }
            }
            d.addingTag = false;
            _waFormPaint();
          } else if (e.key === 'Escape') {
            d.addingTag = false;
            _waFormPaint();
          }
        };

        window.__waFormPhoto = function() {
          // Add flow: Retake returns to the image step (batch queue kept).
          // Manual/edit: poke the hidden input — a straight photo replace.
          if (_waForm && _waForm.mode === 'add') { _showStep1(); return; }
          const inp = document.getElementById('rb-wf-photoin');
          if (inp) inp.click();
        };
        window.__waFormDelete = function() { _waDelete(); };
        // The piece's looks live in the Lookbook — close the form, go there
        window.__waFormLooks = function() {
          if (window.WA && WA.close) { try { WA.close(); } catch (e) {} }
          setTimeout(function() { window.__lkGo && window.__lkGo(); }, 120);
        };
        window.__waLinkSoon = function() {
          _waSoon('Paste a link', 'Drop a product link and Robes files the piece — photo, brand and price included.');
        };
        window.__waRetake = function() { _showStep1(); };

        function _waFormSeedEmpty() {
          _photoDataUrl = '';
          window.__waSawLabel = '';
          window.__waSawBrand = '';
          window.__waSawNotes = '';
          window.__waSawColor = '';
          window.__waSawItemDna = {};
          window.__waSawCat = '';
          window.__waSawL2 = '';
          window.__waSawL3 = '';
          window.__waSawTaxSel = _waTaxTree ? { sheet: '', l2: '', l3: '' } : null;
          window.__rbWaDetail = _waDetailSeed('', '');
        }

        // Add without a photo — same anatomy, empty photo slot, empty fields.
        window.__waManualStart = function() {
          _waFormSeedEmpty();
          _waForm = { mode: 'manual', view: 'details', photo: '', readable: false, revealed: true };
          _setDot(3);
          _waFormPaint('#wa-saw-label');
        };

        // Edit — the SAME form, details open, prefilled from the row. The
        // pass-through columns the form no longer captures (price, fit
        // confidence, sentiment, hero) are simply omitted from the PATCH,
        // so an edit never wipes them.
        function _showEditForm(it) {
          _photoDataUrl = '';
          window.__waSawLabel = it.label || '';
          window.__waSawBrand = it.brand || '';
          window.__waSawNotes = it.notes || '';
          window.__waSawColor = it.color || '';
          window.__waSawItemDna = (it.item_dna && typeof it.item_dna === 'object') ? JSON.parse(JSON.stringify(it.item_dna)) : {};
          window.__waSawCat = it.category || '';
          window.__waSawL2 = it.category_l2 || '';
          window.__waSawL3 = it.category_l3 || '';
          window.__waSawTaxSel = _waTaxTree
            ? { sheet: (it.category_l2 && _WA_L2_SHEET[it.category_l2]) || _WA_LEGACY_TO_SHEET[it.category] || '', l2: it.category_l2 || '', l3: it.category_l3 || '' }
            : null;
          // ADR-002: the values are STORED now, not displayed defaults —
          // the pre-fill put them there and season_source records whether
          // they are Robes' inference or hers. She taps to correct, and
          // *Touched is what promotes this piece's provenance to 'user'.
          window.__rbWaDetail = {
            band: _waItemBand(it),
            wear: _waItemWear(it).slice(),
            bandTouched: false, wearTouched: false,
            addingTag: false,
          };
          _waForm = { mode: 'edit', view: 'details', photo: it.image_url || '', readable: false, revealed: true };
          _setDot(3);
          _waFormPaint();
        }

        function _runStep3(dataUrl, tag) {
          _setDot(3);
          const dna = tag.item_dna || {};
          const initColor = GEMINI_MAP[tag.color] || tag.color || '';
          window.__waSawLabel = tag.label || '';
          window.__waSawBrand = tag.brand || '';
          window.__waSawNotes = dna.ai_generated_notes || tag.notes || '';
          window.__waSawColor = initColor;
          window.__waSawItemDna = dna;
          window.__waSawCat = tag.category || '';
          window.__waSawL2 = tag.category_l2 || '';
          window.__waSawL3 = tag.category_l3 || '';
          // Display category = the taxonomy sheet's L1 (derived from the
          // analysed L2, else the legacy mapping); the stored `category`
          // stays legacy. The cascade fields only mount when the tree landed.
          const dispSheet = (tag.category_l2 && _WA_L2_SHEET[tag.category_l2]) || _WA_LEGACY_TO_SHEET[tag.category] || '';
          window.__waSawTaxSel = _waTaxTree ? { sheet: dispSheet, l2: tag.category_l2 || '', l3: tag.category_l3 || '' } : null;
          window.__rbWaDetail = _waDetailSeed(tag.category, tag.category_l2);
          // A readable piece gets the summary + reveal; an unreadable one
          // goes straight to the open editor — nothing to celebrate yet.
          const readable = !!tag.label;
          _waForm = { mode: 'add', view: readable ? 'summary' : 'details', photo: dataUrl, readable: readable, revealed: false };
          _waFormPaint(readable ? null : '#wa-saw-label');
        }

        window.__waSawSubmit = function() {
          const step = document.querySelector('#wa-modal .fm-step');
          if (!step) return;
          // The bundle's WA.submit silently returns on an empty label, which
          // would leave the CTA stuck on "Saving…" — catch it here instead.
          // The name field lives in the details editor, so open it first.
          if (!(window.__waSawLabel || '').trim()) {
            if (_waForm && _waForm.view !== 'details') window.__waFormView('details');
            const nameEl = document.getElementById('wa-saw-label');
            if (nameEl) {
              nameEl.style.borderColor = '#B0533B';
              nameEl.focus();
              let hint = document.getElementById('wa-saw-namehint');
              if (!hint) {
                hint = document.createElement('div');
                hint.id = 'wa-saw-namehint';
                hint.style.cssText = 'font-size:12px;color:#B0533B;margin:6px 0 0;';
                nameEl.parentNode.appendChild(hint);
              }
              hint.textContent = 'Give the piece a name first — even “black blazer” will do.';
              nameEl.addEventListener('input', function clr() {
                nameEl.style.borderColor = '#D8CEBC';
                if (hint) hint.textContent = '';
                nameEl.removeEventListener('input', clr);
              });
            }
            return;
          }
          // Keep the polished review visible and flip its own CTA to "Saving…"
          // — the bundle form WA.submit reads from is injected into a hidden
          // host instead of swapping the visible step.
          const sawBtn = document.getElementById('wa-saw-cta');
          if (sawBtn) { sawBtn.disabled = true; sawBtn.style.opacity = '0.65'; sawBtn.style.cursor = 'default'; sawBtn.textContent = 'Saving…'; }
          let host = document.getElementById('wa-hidden-form');
          if (!host) {
            host = document.createElement('div');
            host.id = 'wa-hidden-form';
            host.style.display = 'none';
            step.appendChild(host);
          }
          if (_origStepHTML) host.innerHTML = _origStepHTML;
          const lEl  = document.getElementById('wa-label-in');
          const cEl  = document.getElementById('wa-cat');
          const bEl  = document.getElementById('wa-brand');
          const nEl  = document.getElementById('wa-notes');
          const swEl = document.getElementById('wa-sw-name');
          const tileImg  = document.getElementById('wa-tile-img');
          const tileEl   = document.getElementById('wa-tile');
          const tileFill  = document.getElementById('wa-tile-fill');
          const tileEmpty = document.getElementById('wa-tile-empty');
          if (lEl)  lEl.value        = window.__waSawLabel || '';
          if (cEl)  cEl.value        = window.__waSawCat   || '';
          if (bEl)  bEl.value        = window.__waSawBrand || '';
          if (nEl)  nEl.value        = window.__waSawNotes  || '';
          if (swEl) swEl.textContent = window.__waSawColor  || '';
          if (tileImg && _photoDataUrl) tileImg.src = _photoDataUrl;
          if (_photoDataUrl) {
            if (tileEl)   tileEl.classList.add('filled');
            if (tileFill)  tileFill.style.display  = 'block';
            if (tileEmpty) tileEmpty.style.display = 'none';
          }
          setTimeout(() => { window.WA && WA.submit && WA.submit(); }, 50);
        };

        function _patchWA() {
          if (!window.WA || !WA.open || WA.open._rbPatched) return false;
          // Capture the pristine bundle add-form NOW, while .fm-step still
          // holds the static HTML. Without this, _origStepHTML stays empty
          // until the first add-flow open captures it — so a Snap Mine that
          // is the very first WA.open of the session had nothing to restore,
          // and the bundle's open() crashed on a null #wa-label-in whenever
          // a prior flow had already replaced .fm-step. Guarded on the label
          // so we never snapshot our own custom step content.
          if (!_origStepHTML) {
            const step0 = document.querySelector('#wa-modal .fm-step');
            // Guard on .wa-grid — unique to the real bundle form — so we never
            // snapshot a stripped step-1/2/3 state (which only has a dummy
            // #wa-label-in) and poison every later restore.
            if (step0 && step0.querySelector('.wa-grid')) _origStepHTML = step0.innerHTML;
          }
          const _origOpen = WA.open;
          WA.open = function() {
            _photoDataUrl = '';
            // The bundle's open() does $('wa-label-in').value = '' etc. — it
            // needs the bundle form present in .fm-step. If a prior flow left
            // our custom step content there (e.g. a swap → Snap Mine, or the
            // modal closed mid-add without submitting), restore the bundle
            // form first so _origOpen doesn't crash on a null #wa-label-in.
            // Runs in BOTH add and edit modes. On the very first open
            // _origStepHTML is empty and the bundle form is already present,
            // so this is a no-op and the form is captured at line ~843.
            // The bundle's open()/validate() write to a fixed set of fields
            // that live inside .fm-step. Our custom add-steps (and interrupted
            // add flows) can leave .fm-step with SOME or NONE of them — step 1
            // keeps only a dummy #wa-label-in, so a gate on that field alone
            // let the bundle sail past it and crash on the next null (#wa-cat).
            // Guarantee EVERY required field exists before _origOpen: restore
            // the captured bundle form if we have it, then shim any still-
            // missing field. _showStep1 replaces the content 150ms later.
            const _WA_FIELDS = ['wa-label-in', 'wa-cat', 'wa-brand', 'wa-notes', 'wa-sw-name', 'wa-swatches', 'wa-cta'];
            if (_WA_FIELDS.some(id => !document.getElementById(id))) {
              const step = document.querySelector('#wa-modal .fm-step');
              if (step && _origStepHTML) step.innerHTML = _origStepHTML;
              const stillMissing = _WA_FIELDS.filter(id => !document.getElementById(id));
              if (stillMissing.length) {
                const host = document.querySelector('#wa-modal .fm-step') || document.getElementById('wa-modal');
                if (host) {
                  const shim = document.createElement('div');
                  shim.style.display = 'none';
                  host.appendChild(shim);
                  const TAG = { 'wa-cat': 'select', 'wa-notes': 'textarea', 'wa-sw-name': 'span', 'wa-swatches': 'div', 'wa-cta': 'button' };
                  stillMissing.forEach(id => { const el = document.createElement(TAG[id] || 'input'); el.id = id; shim.appendChild(el); });
                }
              }
            }
            try {
              _origOpen.apply(this, arguments);
            } catch (e) {
              // Absolute backstop — the bundle open() must never break Snap Mine.
              console.warn('[robes] bundle WA.open threw, opening modal directly:', e);
              const m = document.getElementById('wa-modal');
              if (m) m.classList.add('open');
              document.body.classList.add('modal-open');
            }
            if (!_waEditId) {
              // Add mode: capture bundle form HTML once, then show photo step
              setTimeout(function() {
                const step = document.querySelector('#wa-modal .fm-step');
                // Only capture the real bundle form (.wa-grid), never a step state
                if (step && !_origStepHTML && step.querySelector('.wa-grid')) _origStepHTML = step.innerHTML;
                _showStep1();
              }, 150);
            } else {
              // Edit mode: the SAME confirm form, details open, prefilled
              // (add/edit redesign 2026-08-05 — the bundle form survives
              // only as the hidden save bridge).
              setTimeout(function() {
                const step = document.querySelector('#wa-modal .fm-step');
                if (step && !_origStepHTML && step.querySelector('.wa-grid')) _origStepHTML = step.innerHTML;
                const it = _waItems.find(function(i) { return String(i.id) === String(_waEditId); });
                if (it) _showEditForm(it);
              }, 150);
            }
          };
          WA.open._rbPatched = true;
          if (WA.close && !WA.close._rbPatched) {
            const _origClose = WA.close;
            WA.close = function() {
              _photoDataUrl = '';
              _waBatchQueue = []; _waBatchTotal = 0; _waBatchDone = 0;
              // Form + tag-axis + taxonomy state must not leak into the next open
              _waForm = null;
              _waPopClose();
              window.__rbWaDetail = null;
              window.__waSawTaxSel = null;
              _origClose.apply(this, arguments);
            };
            WA.close._rbPatched = true;
          }
          // Guard validate — bundle tries to focus #wa-label-in which doesn't exist on steps 1-3
          if (WA.validate && !WA.validate._rbPatched) {
            const _origValidate = WA.validate;
            WA.validate = function() {
              if (!document.getElementById('wa-label-in')) return;
              _origValidate.apply(this, arguments);
            };
            WA.validate._rbPatched = true;
          }
          console.log('[robes-autotag] WA patched');
          return true;
        }

        if (!_patchWA()) {
          const poll = setInterval(function() { if (_patchWA()) clearInterval(poll); }, 200);
        }
      })();




      if (window.WA) {
        WA.submit = async function() {
          const label = (document.getElementById('wa-label-in') || {}).value && document.getElementById('wa-label-in').value.trim();
          if (!label) { const l = document.getElementById('wa-label-in'); if (l) l.focus(); return; }

          const editId = _waEditId;
          const cta = document.getElementById('wa-cta');
          if (cta) { cta.disabled = true; cta.textContent = 'Saving…'; }

          try {
            let imageUrl = editId ? (_waItems.find(i => i.id === editId) || {}).image_url || null : null;

            // Upload new photo if one was selected (data URL in tile)
            const tileImg  = document.getElementById('wa-tile-img');
            const tileFill = document.getElementById('wa-tile-fill');
            const tileSrc  = tileImg ? tileImg.src : '';
            const tileEl   = document.getElementById('wa-tile');
            const isFilled = (tileEl && tileEl.classList.contains('filled')) ||
                             (tileFill && tileFill.style.display === 'block');
            const isDataUrl = tileSrc && tileSrc.startsWith('data:');
            if (isFilled && isDataUrl) {
              const match = tileSrc.match(/^data:([^;]+);base64,(.+)$/);
              if (match) {
                try {
                  const res = await fetch('/api/wardrobe/upload', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ data: match[2], mimeType: match[1] })
                  });
                  const j = await res.json();
                  if (j.url) imageUrl = j.url;
                  else console.warn('Upload returned no URL:', j);
                } catch(uploadErr) { console.warn('Photo upload failed:', uploadErr); }
              }
            }

            const colorName = (document.getElementById('wa-sw-name') || {}).textContent && document.getElementById('wa-sw-name').textContent.trim();
            // Merge current colour + notes into item_dna before saving
            const savedDna = window.__waSawItemDna || {};
            if (colorName) {
              savedDna.display = Object.assign({}, savedDna.display || {}, { editorial_color_name: colorName });
            }
            const notesVal = ((document.getElementById('wa-notes') || {}).value || '').trim() || null;
            if (notesVal) savedDna.ai_generated_notes = notesVal;

            const payload = {
              user_id:   _waUid(),
              label,
              category:  (document.getElementById('wa-cat')   || {}).value || 'Other',
              color:     colorName || null,
              brand:     ((document.getElementById('wa-brand') || {}).value || '').trim() || null,
              notes:     notesVal,
              image_url: imageUrl,
              item_dna:  Object.keys(savedDna).length ? savedDna : undefined,
            };

            // ADR-002: Season -> wardrobe_items.season_band (+ season_source),
            // Wear it for -> the shared tag namespace, written after the row
            // exists. Price / fit_confidence / sentiment / hero_position stay
            // OMITTED — the form doesn't capture them and leaving them off
            // the PATCH preserves whatever an old row carries.
            //
            // season_source flips to 'user' ONLY if she actually touched the
            // chip. Stamping it on every save would erase the inferred/user
            // split the correction-rate signal is made of — a save is not a
            // correction (ADR-002 [C6]).
            const _V2_KEYS = ['season_band', 'season_source'];
            const det = window.__rbWaDetail;
            if (det && _waV2Cols && det.band) {
              payload.season_band = det.band;
              if (det.bandTouched) payload.season_source = 'user';
            }

            // 3-level taxonomy (migration 15). When the cascade UI mounted
            // (add step 3 or edit modal, tree loaded), __waSawTaxSel owns the
            // filing: the stored legacy `category` is DERIVED from the picks
            // (the fold), so it can never disagree with the pair — and the
            // sheet-L1 names the selects display never reach the column.
            const _TAX_KEYS = ['category_l2', 'category_l3'];
            const taxSel = window.__waSawTaxSel;
            if (taxSel) payload.category = _waTaxLegacy(taxSel.sheet, taxSel.l2, taxSel.l3);
            if (_waTaxCols) {
              if (taxSel) {
                payload.category_l2 = taxSel.l2 || null;
                payload.category_l3 = taxSel.l3 || null;
              } else {
                // Degrade path (tree unavailable): a fresh add carries the
                // analyse read; an edit carries the row's saved pair forward.
                const prev = editId ? (_waItems.find(i => i.id === editId) || {}) : null;
                payload.category_l2 = (prev ? prev.category_l2 : window.__waSawL2) || null;
                payload.category_l3 = (prev ? prev.category_l3 : window.__waSawL3) || null;
                // A manual category pick that contradicts the filed L2 drops the
                // pair — L2 must never disagree with the L1 surfaces filter on.
                const okCats = payload.category_l2 ? _WA_TAX_L2[payload.category_l2] : null;
                if (payload.category_l2 && (!okCats || okCats.indexOf(payload.category) === -1)) {
                  payload.category_l2 = null;
                  payload.category_l3 = null;
                }
              }
              if (!payload.category_l2) payload.category_l3 = null;
            }

            // Pre-migration Supabase rejects unknown columns (PGRST204) —
            // strip the tier the error names (taxonomy cols are named in the
            // message; otherwise the v2 fields), remember, and retry so the
            // core save never fails on a schema that hasn't caught up yet.
            // Each pass flips a flag off, so the loop is bounded at 2 retries.
            let created = null;
            for (;;) {
              try {
                if (editId) {
                  await _waFetch('PATCH', 'wardrobe_items?id=eq.' + editId, payload);
                } else {
                  created = await _waFetch('POST', 'wardrobe_items', payload);
                }
                break;
              } catch (err) {
                const msg = String(err && err.message || err);
                if (/PGRST204|column/i.test(msg)) {
                  if (_waTaxCols && /category_l[23]/.test(msg)) {
                    _waTaxCols = false;
                    _TAX_KEYS.forEach(k => delete payload[k]);
                    continue;
                  }
                  if (det && _waV2Cols) {
                    _waV2Cols = false;
                    _V2_KEYS.forEach(k => delete payload[k]);
                    continue;
                  }
                }
                throw err;
              }
            }

            // Tag links, once the row exists. Only when she touched the
            // axis: an untouched add leaves the DB trigger's pre-fill alone
            // (source 'inferred'), which is what keeps the correction rate
            // readable per category.
            try {
              const savedId = editId || (Array.isArray(created) && created[0] && created[0].id) || null;
              if (savedId && det && det.wearTouched) {
                _tgSetLinks('piece', savedId, 'wear_for', det.wear || [], 'user');
              }
            } catch (e) { console.warn('[tags] link write:', e && e.message); }

            if (!editId) _rbTrack('wardrobe_added', { label: payload.label || '', category: payload.category || '' });
            _waEditId = null;
            // Batch mode: keep the modal open and roll the next queued photo
            // into step 2 — closing between pieces made 15 photos feel like
            // 15 chores. (Snapshot the total: closing clears the counters.)
            const batchNext = !editId && _waBatchQueue.length ? _waBatchQueue.shift() : null;
            const batchTotal = _waBatchTotal;
            if (batchNext) _waBatchDone++;
            else _origWAClose();
            await _waLoad();
            if (batchNext) _waShowToast('Piece ' + _waBatchDone + ' of ' + batchTotal + ' added');
            else if (!editId && batchTotal > 1) _waShowToast('All ' + batchTotal + ' pieces in your wardrobe');
            else if (editId) _waShowToast('Piece updated');
            else {
              // A one-line, non-modal payoff on every add (Mary's user
              // testing, 2026-08-21 — the post-add fork modal that used to
              // carry this below 5 pieces is gone; it kept throwing
              // first-session users back into a "style it 3 ways" loop
              // they hadn't asked for).
              const nNow = _waItems.length;
              _waShowToast(nNow >= 15 ? 'Added to wardrobe'
                : 'Added — ' + nNow + (nNow === 1 ? ' piece' : ' pieces') + ' filed. Each one replaces a borrowed piece in your looks.');
            }

            // A pending "Snap mine" swap is waiting on this new piece —
            // apply it now that _waItems has reloaded with the new row.
            if (!editId && typeof _waAfterAdd === 'function') {
              const hook = _waAfterAdd;
              _waAfterAdd = null;
              const newId = (Array.isArray(created) && created[0] && created[0].id != null)
                ? created[0].id
                : (_waItems[0] && _waItems[0].id);
              if (newId != null) { try { hook(newId); } catch (e) { console.warn('[robes] after-add hook:', e); } }
            }

            if (batchNext && typeof _waBatchAdvance === 'function') _waBatchAdvance(batchNext);
          } catch(e) {
            console.error('WA submit:', e);
            // Name the one recoverable case (stale/expired JWT) instead of
            // the generic line — a refresh genuinely fixes it.
            const failMsg = String(e && e.message || '');
            _waShowToast(/401|JWT|expired|invalid token/i.test(failMsg)
              ? 'Your session went quiet — refresh the page and try again'
              : 'Something went wrong — try again');
            if (cta) { cta.disabled = false; cta.textContent = editId ? 'Update piece' : 'Add to wardrobe'; }
            // Re-enable the visible step-3 CTA (add flow) so the user can retry.
            const sawBtn = document.getElementById('wa-saw-cta');
            if (sawBtn) { sawBtn.disabled = false; sawBtn.style.opacity = '1'; sawBtn.style.cursor = 'pointer'; sawBtn.textContent = editId ? 'Update piece →' : 'Add to wardrobe →'; }
          }
        };
      }

      async function _waDelete() {
        if (!_waEditId) return;
        if (!confirm('Remove this piece from your wardrobe?')) return;
        try {
          await _waFetch('DELETE', 'wardrobe_items?id=eq.' + _waEditId, undefined);
          _origWAClose();
          _waEditId = null;
          await _waLoad();
          _waShowToast('Piece removed');
        } catch(e) { _waShowToast('Could not remove piece'); }
      }

      // ═══════════════════════════════════════════════════════════════════
      // Wardrobe v2 — Hero Rack · Refine drawer · Wishlist · add chooser
      // (Claude Design handoff 2026-07-14: "hierarchy over uniformity".)
      // The mock was a UX guide only — everything below renders with the
      // beta's own tokens and card DNA. Persistence needs
      // supabase/wardrobe_v2_migration.sql; until it runs the code degrades
      // gracefully (saves retry without the new columns, hero/wishlist
      // toast "not ready yet") — same convention as the lookbook table.
      // ═══════════════════════════════════════════════════════════════════

      // `var` on purpose — early readers (_waSyncCounts at boot, observer
      // callbacks) must see undefined/default, never throw (TDZ gotcha).
      var _waView = 'all';                 // 'all' | 'wishlist'
