        const parts = [];
        if (Array.isArray(tv.capsule) && tv.capsule.length) parts.push(_lkN(tv.capsule.length, 'piece'));
        if (Array.isArray(tv.looks) && tv.looks.length) parts.push(_lkN(tv.looks.length, 'look'));
        const dr = _lkHolDates(tv);
