        const wantShop = mineOnly ? [] : (gaps.length >= 2 ? gaps : gaps.slice(0, 1));
        _lkAspirational = !mineOnly && gaps.length >= 2;
        _lkBuildGaps = gaps.filter(g => wantShop.indexOf(g) < 0).map(g => g.role);
